#!/usr/bin/env python3
"""
Automated Plant Watering System for Raspberry Pi

Controls two DC motors and two moisture sensors via a TCP command interface.
Uses MCP3008 ADCs on channels 0 and 1, bit-banged SPI, and PWM for motors.
"""

import socket
import threading
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_THRESHOLD = 50
DEFAULT_WATERING_DURATION = 30
MAX_MOISTURE_READINGS = 5
MOISTURE_SENSOR_DELAY = 0.2
HEALTH_CHECK_INTERVAL = 60
TCP_PORT = 12345

# Global state
running = True
threshold = DEFAULT_THRESHOLD
watering_duration = DEFAULT_WATERING_DURATION

# Hardware driver imports (degraded gracefully if unavailable)
try:
    import spidev
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    spidev = None
    DigitalOutputDevice = None
    PWMOutputDevice = None
    GPIOZeroError = Exception
    DeviceClosed = Exception

# MCP3008 ADC driver
class MCP3008:
    """Bit-banged MCP3008 ADC driver for Raspberry Pi."""

    def __init__(self, spi_bus=0, spi_device=0, channel=0):
        if spidev is None:
            raise RuntimeError("spidev library not available")
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = 1000000
            self.spi.mode = 0b00  # SPI mode 0 (CPOL=0, CPHA=0)
            self.channel = channel
        except Exception as e:
            raise RuntimeError(f"Failed to initialize MCP3008 on bus {spi_bus}, device {spi_device}: {e}")

    def read_channel(self):
        """Read a single-ended channel (0-7) from the ADC."""
        if not 0 <= self.channel <= 7:
            raise ValueError("Channel must be between 0 and 7")
        # Build command: start bit (1), single-ended mode (1), channel bits (3)
        command = [1, (8 + self.channel) << 4, 0]
        try:
            response = self.spi.xfer2(command)
            # Extract 10-bit value from response bytes 1 and 2
            value = ((response[1] & 0x03) << 8) + response[2]
            return value
        except Exception as e:
            raise RuntimeError(f"Error reading MCP3008 channel {self.channel}: {e}")

    def close(self):
        """Close the SPI connection."""
        if hasattr(self, 'spi') and self.spi:
            try:
                self.spi.close()
            except Exception:
                pass

# Hardware abstraction layer
class Hardware:
    """Manages motor control, moisture sensors, and TCP socket."""

    def __init__(self):
        self.motor_a_forward = None
        self.motor_a_backward = None
        self.motor_b_clockwise = None
        self.motor_b_counterclockwise = None
        self.motor_a_enable = None
        self.motor_b_enable = None
        self.moisture_sensor_1 = None
        self.moisture_sensor_2 = None
        self.spi = None
        self.tcp_socket = None
        self.tcp_thread = None
        self.lock = threading.Lock()

        # Initialize hardware drivers (degraded gracefully if unavailable)
        try:
            self.motor_a_forward = DigitalOutputDevice(27)
            self.motor_a_backward = DigitalOutputDevice(22)
            self.motor_b_clockwise = DigitalOutputDevice(24)
            self.motor_b_counterclockwise = DigitalOutputDevice(25)
            self.motor_a_enable = PWMOutputDevice(17, frequency=1000)
            self.motor_b_enable = PWMOutputDevice(23, frequency=1000)
            self.spi = MCP3008(spi_bus=0, spi_device=0, channel=0)
            self.spi.close()  # Close SPI after initialization
            logging.info("Hardware initialized successfully")
        except Exception as e:
            logging.warning(f"Hardware initialization failed: {e}. Running in degraded mode.")

    def set_motor_speed(self, motor_a_speed, motor_b_speed):
        """Set motor speeds (0.0 to 1.0)."""
        with self.lock:
            if self.motor_a_enable and self.motor_b_enable:
                self.motor_a_enable.value = motor_a_speed
                self.motor_b_enable.value = motor_b_speed

    def set_motor_direction(self, motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counterclockwise):
        """Set motor directions."""
        with self.lock:
            if self.motor_a_forward and self.motor_a_backward and self.motor_b_clockwise and self.motor_b_counterclockwise:
                self.motor_a_forward.value = motor_a_forward
                self.motor_a_backward.value = motor_a_backward
                self.motor_b_clockwise.value = motor_b_clockwise
                self.motor_b_counterclockwise.value = motor_b_counterclockwise

    def read_moisture_sensor(self, sensor_number):
        """Read moisture sensor data. Returns -1 on error."""
        if sensor_number == 1:
            sensor = self.moisture_sensor_1
        elif sensor_number == 2:
            sensor = self.moisture_sensor_2
        else:
            return -1

        if sensor is None:
            return -1

        try:
            readings = []
            for _ in range(MAX_MOISTURE_READINGS):
                readings.append(sensor.read_channel())
                time.sleep(MOISTURE_SENSOR_DELAY)
            return sum(readings) / len(readings)
        except Exception as e:
            logging.error(f"Error reading moisture sensor {sensor_number}: {e}")
            return -1

    def start_watering(self, duration):
        """Start watering process."""
        logging.info("Starting watering process...")
        self.set_motor_speed(0.5, 0.5)
        self.set_motor_direction(True, False, True, False)
        time.sleep(duration)
        self.stop_watering()

    def stop_watering(self):
        """Stop watering process."""
        logging.info("Stopping watering process...")
        self.set_motor_speed(0, 0)
        self.set_motor_direction(False, False, False, False)

    def health_check(self):
        """Perform periodic health checks."""
        logging.info("Starting health check...")
        try:
            if self.motor_a_enable and self.motor_b_enable:
                self.motor_a_enable.value = 0.5
                self.motor_b_enable.value = 0.5
                time.sleep(1)
                self.motor_a_enable.value = 0
                self.motor_b_enable.value = 0
        except Exception as e:
            logging.error(f"Error during health check: {e}")
        logging.info("Health check complete.")

    def cleanup(self):
        """Release all resources."""
        logging.info("Cleaning up resources...")
        self.stop_watering()
        if self.motor_a_enable:
            self.motor_a_enable.close()
        if self.motor_b_enable:
            self.motor_b_enable.close()
        if self.motor_a_forward:
            self.motor_a_forward.close()
        if self.motor_a_backward:
            self.motor_a_backward.close()
        if self.motor_b_clockwise:
            self.motor_b_clockwise.close()
        if self.motor_b_counterclockwise:
            self.motor_b_counterclockwise.close()
        if self.spi:
            self.spi.close()
        if self.tcp_socket:
            self.tcp_socket.close()
            logging.info("TCP socket closed.")

# TCP socket handler
def handle_tcp_connection(hardware, client_socket):
    """Handle a single TCP connection."""
    logging.info(f"Connected by {client_socket.getpeername()}")
    try:
        while running:
            try:
                data = client_socket.recv(1024).decode('utf-8').strip()
                if not data:
                    break
                logging.info(f"Received command: {data}")
                parts = data.split()
                if not parts:
                    continue
                command = parts[0]

                if command == "WATER_PLANT_1":
                    moisture_1 = hardware.read_moisture_sensor(1)
                    if moisture_1 != -1:
                        if moisture_1 < threshold:
                            logging.info(f"Moisture level low ({moisture_1}%) for plant 1. Watering...")
                            hardware.start_watering(watering_duration)
                        else:
                            logging.info(f"Moisture level adequate ({moisture_1}%) for plant 1.")
                    else:
                        logging.error("Failed to read moisture sensor 1.")
                elif command == "WATER_PLANT_2":
                    moisture_2 = hardware.read_moisture_sensor(2)
                    if moisture_2 != -1:
                        if moisture_2 < threshold:
                            logging.info(f"Moisture level low ({moisture_2}%) for plant 2. Watering...")
                            hardware.start_watering(watering_duration)
                        else:
                            logging.info(f"Moisture level adequate ({moisture_2}%) for plant 2.")
                    else:
                        logging.error("Failed to read moisture sensor 2.")
                elif command == "GET_SENSOR_DATA":
                    moisture_1 = hardware.read_moisture_sensor(1)
                    moisture_2 = hardware.read_moisture_sensor(2)
                    if moisture_1 != -1 and moisture_2 != -1:
                        response = f"SENSOR_DATA,Plant_1_Moisture:{moisture_1},Plant_2_Moisture:{moisture_2}"
                        client_socket.sendall(response.encode('utf-8'))
                    else:
                        logging.error("Failed to read moisture sensors.")
                elif command == "SET_THRESHOLD":
                    if len(parts) > 1:
                        try:
                            new_threshold = int(parts[1])
                            if 0 <= new_threshold <= 100:
                                global threshold
                                threshold = new_threshold
                                logging.info(f"Threshold set to {threshold}%")
                                client_socket.sendall(b"Threshold set successfully")
                            else:
                                client_socket.sendall(b"Invalid threshold value. Must be between 0 and 100.")
                        except ValueError:
                            client_socket.sendall(b"Invalid threshold value. Must be an integer.")
                    else:
                        client_socket.sendall(b"Usage: SET_THRESHOLD <value>")
                elif command == "SET_WATERING_DURATION":
                    if len(parts) > 1:
                        try:
                            new_duration = int(parts[1])
                            if 0 <= new_duration <= 60:
                                global watering_duration
                                watering_duration = new_duration
                                logging.info(f"Watering duration set to {watering_duration} seconds")
                                client_socket.sendall(b"Watering duration set successfully")
                            else:
                                client_socket.sendall(b"Invalid watering duration value. Must be between 0 and 60 seconds.")
                        except ValueError:
                            client_socket.sendall(b"Invalid watering duration value. Must be an integer.")
                    else:
                        client_socket.sendall(b"Usage: SET_WATERING_DURATION <value>")
                elif command == "EXIT":
                    logging.info("Exit command received.")
                    break
                else:
                    client_socket.sendall(b"Invalid command. Use WATER_PLANT_1, WATER_PLANT_2, GET_SENSOR_DATA, SET_THRESHOLD, SET_WATERING_DURATION, or EXIT.")
            except socket.timeout:
                logging.warning("Socket timeout. Reconnecting...")
                break
            except Exception as e:
                logging.error(f"Error handling TCP connection: {e}")
                break
    except Exception as e:
        logging.error(f"Error setting up TCP connection: {e}")
    finally:
        client_socket.close()
        logging.info(f"Connection closed by {client_socket.getpeername()}")

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    logging.info("Shutdown signal received.")
    running = False

# Main function
def main():
    global running, threshold, watering_duration

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    hardware = Hardware()

    # Start TCP server
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(('0.0.0.0', TCP_PORT))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logging.info(f"TCP server listening on port {TCP_PORT}")

        while running:
            try:
                client_socket, client_address = server_socket.accept()
                client_socket.settimeout(1.0)
                thread = threading.Thread(target=handle_tcp_connection, args=(hardware, client_socket))
                thread.daemon = True
                thread.start()
            except socket.timeout:
                continue
            except Exception as e:
                logging.error(f"Error accepting connection: {e}")
                break
    except Exception as e:
        logging.error(f"Failed to start TCP server: {e}")
    finally:
        hardware.cleanup()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

