import RPi.GPIO as GPIO
import time
import sys

# Configuration
GAS_SENSOR_PIN = 16
WARNING_LED_PIN = 12
SAMPLE_INTERVAL = 0.5  # seconds
LOW_THRESHOLD_COUNT = 3
FLASH_ON_TIME = 0.2  # seconds
FLASH_OFF_TIME = 0.2  # seconds

def setup_gpio():
    """Initialize GPIO pins with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GAS_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(WARNING_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
