import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0

running = True

def signal_handler(sig, frame):
    global running
    running = False

def format_value(value):
    if value is None:
        return "N/A"
    try:
        return str(value)
    except (TypeError, ValueError):
        return "N/A"

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    i2c = None
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c)
        print("MAX30102 initialized on I2C bus.")
    except Exception as e:
        print(f"Fatal: Failed to initialize MAX30102: {e}")
        sys.exit(1)

    peaks = []
    last_sample_time = time.monotonic()

    try:
        while running:
            now = time.monotonic()
            elapsed = now - last_sample_time
            if elapsed >= SAMPLE_INTERVAL:
                last_sample_time = now

                try:
                    ir_raw = sensor.ir_raw
                    red_raw = sensor.red_raw
                except Exception as e:
                    print(f"Warning: I2C read error: {e}")
                    time.sleep(SAMPLE_INTERVAL)
                    continue

                if ir_raw is None or red_raw is None:
                    print("Warning: Sensor returned None for raw data.")
                    time.sleep(SAMPLE_INTERVAL)
                    continue

                peaks.append(ir_raw)
                if len(peaks) > int(WINDOW_SECONDS / SAMPLE_INTERVAL):
                    peaks.pop(0)

                if len(peaks) == 0:
                    hr = 0.0
                else:
                    # Estimate BPM from peaks (approximate peak spacing)
                    peak_spacing = SAMPLE_INTERVAL / len(peaks)
                    hr = 60.0 / peak_spacing

                timestamp = time.strftime("%Y-%m-%dT%H:%M:%S")
                log_entry = f"{timestamp} - HR: {format_value(hr)}\n"

                try:
                    with open(LOG_FILE, "a") as f:
                        f.write(log_entry)
                except Exception as e:
                    print(f"Warning: Failed to write to log file: {e}")

                print(f"HR: {format_value(hr)}")

            time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if sensor is not None:
            try:
                sensor.deinit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

