import cv2
import time
import signal
import sys
import numpy as np
from gpiozero import LED, Button, AngularServo

# Constants
CAMERA_INDEX = 0
FACE_CASCADE_PATH = "/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml"
WINDOW_NAME = "Human Detection"
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQUENCY = 50
SERVO_INCREMENT = 20
SERVO_SLEEP = 0.02
RESIZE_WIDTH = 32

# Global resources for cleanup
camera = None
led = None
button = None
servo = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global camera, led, button, servo
    print("\nCleaning up resources...")
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
        camera = None
    cv2.destroyAllWindows()
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None
    if servo is not None:
        try:
            servo.close()
        except Exception:
            pass
        servo = None
    print("Cleanup complete.")

def initialize_camera():
    global camera
    camera = cv2.VideoCapture(CAMERA_INDEX)
    if not camera.isOpened():
        raise IOError("Cannot open camera at index 0")
    return camera

def initialize_face_detector(cascade_path):
    face_cascade = cv2.CascadeClassifier(cascade_path)
    if face_cascade.empty():
        raise IOError("Failed to load face cascade classifier")
    return face_cascade

def initialize_gpio():
    global led, button, servo
    try:
        led = LED(LED_PIN)
        button = Button(BUTTON_PIN, pull_up=True)
        servo = AngularServo(SERVO_PIN, min_angle=0, max_angle=180, initial_angle=90, frame_width=1.0 / SERVO_FREQUENCY)
    except Exception as e:
        print(f"Warning: GPIO initialization failed: {e}")
        led = None
        button = None
        servo = None

def detect_faces(image, face_cascade):
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
    return faces

def draw_rectangles(image, faces):
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (0, 255, 0), 2)

def control_servo(servo_obj, faces):
    if not faces:
        return
    x, y, w, h = faces[0]
    center_x = x + w / 2
    center_y = y + h / 2
    if center_x > w / 2:
        angle = 90 - (center_x - w / 2) / w * 90
    else:
        angle = (center_x - w / 2) / w * 90
    angle = max(0, min(180, angle))
    try:
        servo_obj.angle = angle
    except Exception as e:
        print(f"Warning: Failed to set servo angle: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        initialize_gpio()
        camera = initialize_camera()
        face_cascade = initialize_face_detector(FACE_CASCADE_PATH)
    except Exception as e:
        print(f"Initialization error: {e}")
        cleanup()
        sys.exit(0)

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                print("Error: Failed to grab frame from camera")
                break

            resized_frame = cv2.resize(frame, (RESIZE_WIDTH, int(frame.shape[0] * RESIZE_WIDTH / frame.shape[1])))
            faces = detect_faces(resized_frame, face_cascade)

            draw_rectangles(resized_frame, faces)
            control_servo(servo, faces)

            if led is not None:
                led.on() if len(faces) > 0 else led.off()

            cv2.imshow(WINDOW_NAME, resized_frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    except Exception as e:
        print(f"Display error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

