import cv2
import numpy as np
import time
import signal
import sys

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_camera(max_attempts=3, delay=2):
    """Initializes the Raspberry Pi camera with retry logic."""
    for attempt in range(max_attempts):
        try:
            camera = cv2.VideoCapture(0)
            if not camera.isOpened():
                raise IOError("Cannot open camera")
            return camera
        except Exception as e:
            print(f"Camera initialization attempt {attempt + 1}/{max_attempts} failed: {e}")
            if attempt < max_attempts - 1:
                time.sleep(delay)
    return None

def process_frame(frame, min_radius=10):
    """Processes a single frame to detect and track green objects."""
    hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv_frame, np.array([29, 86, 6]), np.array([64, 255, 255]))
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    positions = []
    for contour in contours:
        if cv2.contourArea(contour) > min_radius:
            x, y, w, h = cv2.boundingRect(contour)
            positions.append((x + w // 2, y + h // 2))

    return positions

def draw_trail(frame, positions, max_positions=64):
    """Draws a trail of positions on the frame."""
    for i in range(1, len(positions)):
        if positions[i - 1] is None or positions[i] is None:
            continue
        cv2.line(frame, positions[i - 1], positions[i], (0, 255, 0), 2)
    return frame

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = initialize_camera()
    if camera is None:
        print("Failed to initialize camera. Exiting.")
        sys.exit(1)

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                print("Failed to capture frame. Exiting.")
                break

            frame = cv2.resize(frame, (600, int(frame.shape[0] * 600 / frame.shape[1])))
            positions = process_frame(frame)
            frame = draw_trail(frame, positions)

            cv2.imshow("Frame", frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

