import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

# Constants
CAMERA_INDEX = 0
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 9600
ROI_SIZE = 10
MIN_CONTOUR_AREA = 500
RECTANGLE_COLOR = (255, 0, 0)
RECTANGLE_THICKNESS = 2
DEAD_ZONE_HALF_EXTENT = 50

# Global state
tracking_enabled = True
cap = None
ser = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def cleanup():
    global cap, ser
    if cap is not None:
        cap.release()
    if ser is not None and ser.is_open:
        ser.close()
    cv2.destroyAllWindows()

def get_serial_ports():
    try:
        return [p.device for p in serial.tools.list_ports.comports()]
    except Exception as e:
        print(f"Warning: Could not list serial ports: {e}", file=sys.stderr)
        return []

def open_serial_port(port, baudrate):
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        print(f"Serial port {port} opened at {baudrate} baud.")
        return True
    except serial.SerialException as e:
        print(f"Warning: Could not open serial port {port}: {e}", file=sys.stderr)
        return False

def find_ball(frame):
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    roi = hsv[ROI_SIZE:hsv.shape[0] - ROI_SIZE, ROI_SIZE:hsv.shape[1] - ROI_SIZE]
    h_min, s_min, v_min = np.min(roi[:, :, 0]), np.min(roi[:, :, 1]), np.min(roi[:, :, 2])
    h_max, s_max, v_max = np.max(roi[:, :, 0]), np.max(roi[:, :, 1]), np.max(roi[:, :, 2])
    mask = cv2.inRange(hsv, np.array([h_min, s_min, v_min]), np.array([h_max, s_max, v_max]))
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    for contour in contours:
        if cv2.contourArea(contour) > MIN_CONTOUR_AREA:
            x, y, w, h = cv2.boundingRect(contour)
            cv2.rectangle(frame, (x, y), (x + w, y + h), RECTANGLE_COLOR, RECTANGLE_THICKNESS)
            return x + w // 2, y + h // 2
    return None, None

def classify_ball_position(ball_x, ball_y):
    if ball_x > frame.shape[1] - DEAD_ZONE_HALF_EXTENT and ball_y > frame.shape[0] - DEAD_ZONE_HALF_EXTENT:
        return '1'  # Bottom Right
    elif ball_x > frame.shape[1] - DEAD_ZONE_HALF_EXTENT and ball_y < DEAD_ZONE_HALF_EXTENT:
        return '2'  # Top Right
    elif ball_x < DEAD_ZONE_HALF_EXTENT and ball_y > frame.shape[0] - DEAD_ZONE_HALF_EXTENT:
        return '3'  # Bottom Left
    elif ball_x < DEAD_ZONE_HALF_EXTENT and ball_y < DEAD_ZONE_HALF_EXTENT:
        return '4'  # Top Left
    else:
        return '5'  # Center

def main():
    global cap, ser, tracking_enabled, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_ports = get_serial_ports()
    if SERIAL_PORT not in serial_ports:
        print(f"Warning: Serial port {SERIAL_PORT} not found. Continuing without serial output.")

    if open_serial_port(SERIAL_PORT, SERIAL_BAUDRATE):
        tracking_enabled = True
    else:
        tracking_enabled = False

    cap = cv2.VideoCapture(CAMERA_INDEX)
    if not cap.isOpened():
        print("Error: Could not open camera.", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.", file=sys.stderr)
                break

            ball_x, ball_y = find_ball(frame)
            if ball_x is not None and ball_y is not None:
                position = classify_ball_position(ball_x, ball_y)
                if tracking_enabled and ser is not None and ser.is_open:
                    try:
                        ser.write(position.encode('ascii'))
                    except serial.SerialException as e:
                        print(f"Warning: Could not write to serial port: {e}", file=sys.stderr)

            cv2.imshow('Frame', frame)
            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                h_min, s_min, v_min = cv2.min(frame[:, :, 0]), np.min(frame[:, :, 1]), np.min(frame[:, :, 2])
                h_max, s_max, v_max = np.max(frame[:, :, 0]), np.max(frame[:, :, 1]), np.max(frame[:, :, 2])
                print(f"Min HSV: ({h_min}, {s_min}, {v_min})")
                print(f"Max HSV: ({h_max}, {s_max}, {v_max})")
            elif key == ord('o'):
                tracking_enabled = not tracking_enabled
                print(f"Tracking enabled: {tracking_enabled}")
            elif key == 27:
                break
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

