import json
import logging
import signal
import sys
import time
from collections import deque

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError) as exc:
    GPIO = None

DEFAULT_CONFIG = {
    'offset': 0.0,
    'max_distance': 200.0,
    'low': 10.0,
    'high': 180.0,
    'alert_repeat_delay': 60,
    'log_file': 'water_level.log',
}

SENSOR_PINS = {
    1: {'trigger': 17, 'echo': 18},
    2: {'trigger': 22, 'echo': 23},
    3: {'trigger': 24, 'echo': 25},
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(path='config.json'):
    try:
        with open(path, 'r') as fh:
            cfg = json.load(fh)
    except FileNotFoundError:
        logging.warning('config.json not found; using defaults.')
        cfg = DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as exc:
        logging.error('config.json is invalid JSON: %s; using defaults.', exc)
        cfg = DEFAULT_CONFIG.copy()
    except OSError as exc:
        logging.error('Cannot read config.json: %s; using defaults.', exc)
        cfg = DEFAULT_CONFIG.copy()

    for key, val in DEFAULT_CONFIG.items():
        if key not in cfg:
            cfg[key] = val

    return cfg


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )
    logging.info('Logging initialized to %s', log_file)


def setup_gpio():
    if GPIO is None:
        logging.warning('RPi.GPIO not available; running in mock mode.')
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in SENSOR_PINS.values():
            GPIO.setup(pin['trigger'], GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(pin['echo'], GPIO.IN)
        logging.info('GPIO initialized successfully.')
        return True
    except Exception as exc:
        logging.error('GPIO initialization failed: %s', exc)
        return False


def read_distance(trigger_pin, echo_pin, max_distance=200.0):
    if GPIO is None:
        return None
    try:
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, GPIO.LOW)

        timeout_start = time.time()
        while GPIO.input(echo_pin) == 0:
            if time.time() - timeout_start > 0.05:
                logging.warning('Echo start timeout on trigger %d.', trigger_pin)
                return None

        pulse_start = time.time()

        timeout_start = time.time()
        while GPIO.input(echo_pin) == 1:
            if time.time() - timeout_start > 0.05:
                logging.warning('Echo end timeout on trigger %d.', trigger_pin)
                return None

        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150.0
        distance = max(0.0, min(distance, max_distance))
        return distance

    except Exception as exc:
        logging.error('Error reading distance on trigger %d: %s', trigger_pin, exc)
        return None


def get_median_distance(trigger_pin, echo_pin, max_distance=200.0, num_samples=3):
    distances = []
    for _ in range(num_samples):
        dist = read_distance(trigger_pin, echo_pin, max_distance)
        if dist is not None:
            distances.append(dist)
        time.sleep(0.05)
    if not distances:
        return None
    return sorted(distances)[len(distances) // 2]


def get_water_level(trigger_pin, echo_pin, offset, max_distance, low_threshold, high_threshold):
    median_distance = get_median_distance(trigger_pin, echo_pin, max_distance)
    if median_distance is None:
        return None
    water_level = median_distance - offset
    water_level = max(0.0, min(water_level, max_distance))
    if water_level < low_threshold or water_level > high_threshold:
        return None
    return water_level


def check_alert(water_level, low_threshold, high_threshold, alert_repeat_delay, last_alert_time):
    if water_level is None:
        return last_alert_time
    if water_level < low_threshold or water_level > high_threshold:
        now = time.time()
        if now - last_alert_time > alert_repeat_delay:
            logging.warning('Water level alert: %.1f cm', water_level)
            return now
    return last_alert_time


def cleanup_gpio():
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logging.info('GPIO cleaned up.')
        except Exception as exc:
            logging.error('Error during GPIO cleanup: %s', exc)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cfg = load_config()
    setup_logging(cfg['log_file'])
    if not setup_gpio():
        logging.error('GPIO initialization failed; exiting.')
        sys.exit(0)

    last_alert_time = 0.0
    valid_readings = deque(maxlen=3)

    try:
        while _running:
            for sensor_id, pin_cfg in SENSOR_PINS.items():
                trigger_pin = pin_cfg['trigger']
                echo_pin = pin_cfg['echo']
                offset = cfg['offset']
                max_distance = cfg['max_distance']
                low_threshold = cfg['low']
                high_threshold = cfg['high']
                alert_repeat_delay = cfg['alert_repeat_delay']

                water_level = get_water_level(trigger_pin, echo_pin, offset, max_distance, low_threshold, high_threshold)
                if water_level is not None:
                    valid_readings.append(water_level)
                    avg_level = sum(valid_readings) / len(valid_readings)
                    logging.info('Sensor %d: %.1f cm (avg: %.1f cm)', sensor_id, water_level, avg_level)
                else:
                    logging.warning('Sensor %d: read failed.', sensor_id)

                last_alert_time = check_alert(water_level, low_threshold, high_threshold, alert_repeat_delay, last_alert_time)

            time.sleep(5)

    except Exception as exc:
        logging.error('Unexpected error in main loop: %s', exc)
    finally:
        cleanup_gpio()
        logging.info('Program terminated.')


if __name__ == '__main__':
    main()

