import cv2
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraApp:
    def __init__(self, camera_index=0, display_window_name="Output Image", roi_start=(10, 40), roi_end=(150, 280), framerate=10):
        self.camera_index = camera_index
        self.display_window_name = display_window_name
        self.roi_start = roi_start
        self.roi_end = roi_end
        self.framerate = framerate
        self.cap = None
        self.running = True

    def initialize_camera(self):
        try:
            self.cap = cv2.VideoCapture(self.camera_index)
            if not self.cap.isOpened():
                raise IOError(f"Cannot open camera at index {self.camera_index}")
            self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
            self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
            self.cap.set(cv2.CAP_PROP_FPS, self.framerate)
            actual_fps = self.cap.get(cv2.CAP_PROP_FPS)
            logging.info(f"Camera initialized at index {self.camera_index}, {actual_fps} fps")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.cap = None
            raise

    def extract_roi(self, frame):
        try:
            return frame[self.roi_start[1]:self.roi_end[1], self.roi_start[0]:self.roi_end[0]]
        except Exception as e:
            logging.error(f"Error extracting ROI: {e}")
            return None

    def display_image(self, image):
        try:
            cv2.imshow(self.display_window_name, image)
        except Exception as e:
            logging.error(f"Error displaying image: {e}")

    def run(self):
        if not self.cap:
            logging.error("Camera not initialized. Exiting.")
            return

        try:
            while self.running:
                ret, frame = self.cap.read()
                if not ret:
                    logging.warning("Failed to grab frame. Retrying...")
                    time.sleep(0.1)
                    continue

                roi = self.extract_roi(frame)
                if roi is None:
                    continue

                self.display_image(roi)

                key = cv2.waitKey(1) & 0xFF
                if key == 10:  # Enter key
                    logging.info("Enter key pressed. Exiting...")
                    break
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received. Exiting...")
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up resources...")
        if self.cap and self.cap.isOpened():
            self.cap.release()
            logging.info("Camera released.")
        cv2.destroyAllWindows()
        logging.info("Windows closed.")

def main():
    app = CameraApp()

    def signal_handler(sig, frame):
        logging.info(f"Signal {sig} received. Shutting down...")
        app.running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        app.initialize_camera()
        app.run()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

