import serial
import sys

BLUETOOTH_PORT = '/dev/rfcomm4'
BAUD_RATE = 38400

def main():
    bluetooth_connection = None
    try:
        bluetooth_connection = serial.Serial(
            port=BLUETOOTH_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
        print(f"Connected to Bluetooth device on {BLUETOOTH_PORT} at {BAUD_RATE} baud.")

        while True:
            try:
                user_input = input('Enter message to send (or Ctrl+C to quit): ')
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == 'q':
                print("Quit command received.")
                break

            try:
                encoded_message = user_input.encode('utf-8')
                bytes_written = bluetooth_connection.write(encoded_message)
                bluetooth_connection.flush()
                print(f"Sent {bytes_written} bytes: {user_input}")
            except serial.SerialException as e:
                print(f"Error writing to Bluetooth device: {e}", file=sys.stderr)
                break
            except OSError as e:
                print(f"OS error writing to Bluetooth device: {e}", file=sys.stderr)
                break

    except serial.SerialException as e:
        print(f"Error opening Bluetooth device: {e}", file=sys.stderr)
    except OSError as e:
        print(f"OS error opening Bluetooth device: {e}", file=sys.stderr)
    finally:
        if bluetooth_connection is not None and bluetooth_connection.is_open:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()

