import cv2
import signal
import sys
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Signal received, shutting down...")

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def initialize_camera(camera_index=0):
    try:
        camera = cv2.VideoCapture(camera_index)
        if not camera.isOpened():
            raise IOError(f"Cannot open camera at index {camera_index}")
        return camera
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def load_face_detector(cascade_path="haarcascade_frontalface_default.xml"):
    try:
        face_detector = cv2.CascadeClassifier(cascade_path)
        if face_detector.empty():
            raise IOError(f"Unable to load face detector from {cascade_path}")
        return face_detector
    except Exception as e:
        logging.error(f"Error loading face detector: {e}")
        return None

def detect_faces(image, face_detector):
    try:
        gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        faces = face_detector.detectMultiScale(gray_image, scaleFactor=1.1, minNeighbors=5)
        return faces
    except Exception as e:
        logging.error(f"Error detecting faces: {e}")
        return []

def draw_face_rectangles(image, faces):
    try:
        for (x, y, width, height) in faces:
            cv2.rectangle(image, (x, y), (x + width, y + height), (255, 0, 0), 2)
    except Exception as e:
        logging.error(f"Error drawing face rectangles: {e}")

