import io
import logging
import signal
import threading
import traceback
from typing import Callable, Optional

import numpy as np
from PIL import Image

try:
    import cv2
except ImportError:
    cv2 = None

try:
    import websockets
except ImportError:
    websockets = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("camera_stream")

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
DEFAULT_FRAMERATE = 10
DEFAULT_RESOLUTION = (640, 480)
LOW_RESOLUTION = (320, 240)
JPEG_QUALITY = 85

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_camera: Optional["Camera"] = None
_shutdown = threading.Event()


class Camera:
    """Threaded camera wrapper that streams RGB888 frames to WebSocket clients."""

    def __init__(
        self,
        framerate: int = DEFAULT_FRAMERATE,
        resolution: tuple[int, int] = DEFAULT_RESOLUTION,
        low_resolution: tuple[int, int] = LOW_RESOLUTION,
        detect_motion_function: Optional[Callable[[np.ndarray, np.ndarray], None]] = None,
    ) -> None:
        self.framerate = framerate
        self.resolution = resolution
        self.low_resolution = low_resolution
        self.detect_motion_function = detect_motion_function
        self.frame_lock = threading.Lock()
        self.prev_frame: Optional[np.ndarray] = None
        self.frame_buffer: io.BytesIO = io.BytesIO()
        self.buffer_lock = threading.Lock()
        self.camera_thread: Optional[threading.Thread] = None
        self.camera: Optional[cv2.VideoCapture] = None
        self._closed = False

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def start(self) -> None:
        """Initialize the camera and start the background thread."""
        if self._closed:
            log.warning("Camera already started; ignoring start request.")
            return
        if self.camera is not None:
            log.warning("Camera already initialized; ignoring start request.")
            return

        if cv2 is None:
            log.error("cv2 is not installed; cannot initialize camera.")
            return

        self.camera = cv2.VideoCapture(0)
        if not self.camera.isOpened():
            log.error("Failed to open camera index 0.")
            self.camera = None
            return

        self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, self.resolution[0])
        self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, self.resolution[1])
        self.camera.set(cv2.CAP_PROP_FPS, self.framerate)

        if self.camera.get(cv2.CAP_PROP_FPS) != self.framerate:
            log.warning(
                f"Requested {self.framerate} fps, got {self.camera.get(cv2.CAP_PROP_FPS)} fps."
            )

        self.camera_thread = threading.Thread(
            target=self._capture_loop, daemon=True, name="CameraThread"
        )
        self.camera_thread.start()
        log.info("Camera started successfully.")

    def stop(self) -> None:
        """Stop the camera thread and release resources."""
        if self._closed:
            return
        self._closed = True
        log.info("Stopping camera...")

        if self.camera_thread is not None and self.camera_thread.is_alive():
            self.camera_thread.join(timeout=2.0)
            if self.camera_thread.is_alive():
                log.warning("Camera thread did not stop within timeout.")

        if self.camera is not None:
            self.camera.release()
            self.camera = None

        log.info("Camera stopped.")

    def has_connections(self) -> bool:
        """Return True if any WebSocketHandler has a live connection."""
        return bool(WebSocketHandler.connections)

    def broadcast(self, data: bytes) -> None:
        """Broadcast data to all connected WebSocket clients."""
        if not self.has_connections():
            return

        try:
            with self.buffer_lock:
                self.frame_buffer.seek(0)
                data_bytes = self.frame_buffer.read()
                self.frame_buffer.seek(0)
                self.frame_buffer.truncate()

            for handler in list(WebSocketHandler.connections.values()):
                if not handler.closed:
                    handler.broadcast(data_bytes)
        except Exception as exc:
            log.error(f"Broadcast error: {exc}")

    # ------------------------------------------------------------------
    # Internal capture loop
    # ------------------------------------------------------------------
    def _capture_loop(self) -> None:
        """Continuously capture frames and detect motion."""
        if self.camera is None:
            log.error("Camera not initialized in capture loop.")
            return

        try:
            while not _shutdown.is_set():
                ret, frame = self.camera.read()
                if not ret or frame is None:
                    log.warning("Failed to capture frame from camera.")
                    break

                with self.frame_lock:
                    self.prev_frame = frame.copy()

                if self.detect_motion_function is not None:
                    try:
                        self.detect_motion_function(self.prev_frame, frame)
                    except Exception as exc:
                        log.error(f"Motion detection error: {exc}")

                # Low-resolution JPEG stream
                with self.buffer_lock:
                    self.frame_buffer.seek(0)
                    self.frame_buffer.truncate()
                    success, encoded = cv2.imencode(
                        ".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, JPEG_QUALITY]
                    )
                    if not success:
                        log.warning("JPEG encoding failed; skipping broadcast.")
                        continue
                    self.frame_buffer.write(encoded.tobytes())

                _shutdown.wait(1.0 / self.framerate)

        except Exception as exc:
            log.error(f"Capture loop error: {exc}\n{traceback.format_exc()}")
        finally:
            self.stop()


class WebSocketHandler:
    """Manages WebSocket connections and broadcasts camera frames."""

    connections: dict[websockets.WebSocketServer, "WebSocketHandler"] = {}

    def __init__(self, websocket: websockets.WebSocketServer) -> None:
        self.websocket = websocket
        self.closed = False
        self.buffer: io.BytesIO = io.BytesIO()
        self.buffer_lock = threading.Lock()

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    @classmethod
    def has_connections(cls) -> bool:
        return bool(cls.connections)

    @classmethod
    def broadcast(cls, data: bytes) -> None:
        """Broadcast data to all connected WebSocket clients."""
        for handler in list(cls.connections.values()):
            if not handler.closed:
                handler.broadcast(data)

    def broadcast_frame(self) -> None:
        """Broadcast the latest frame buffer."""
        if not self.has_connections():
            return

        try:
            with self.buffer_lock:
                self.buffer.seek(0)
                data_bytes = self.buffer.read()
                self.buffer.seek(0)
                self.buffer.truncate()

            for handler in list(self.connections.values()):
                if not handler.closed:
                    handler.broadcast(data_bytes)
        except Exception as exc:
            log.error(f"Broadcast error: {exc}")

    def handle(self) -> None:
        """Main WebSocket handler loop."""
        try:
            async with self.websocket:
                self.connections[self.websocket] = self
                log.info(f"WebSocket connection established from {self.websocket.remote_address}")

                while not self.closed:
                    try:
                        await self.websocket.wait_for_message()
                    except websockets.exceptions.ConnectionClosedError:
                        break
                    except Exception as exc:
                        log.error(f"Message receive error: {exc}")
                        break

                    try:
                        message = await self.websocket.recv()
                    except websockets.exceptions.ConnectionClosedError:
                        break
                    except Exception as exc:
                        log.error(f"Message receive error: {exc}")
                        break

                    if message is None:
                        continue

                    try:
                        with self.buffer_lock:
                            self.buffer.seek(0)
                            self.buffer.truncate()
                            self.buffer.write(message)
                    except Exception as exc:
                        log.error(f"Buffer write error: {exc}")
                        break

                    self.broadcast_frame()

        except Exception as exc:
            log.error(f"WebSocket handler error: {exc}\n{traceback.format_exc()}")
        finally:
            self.close()

    def close(self) -> None:
        """Close the WebSocket connection and remove from the pool."""
        if self.closed:
            return
        self.closed = True
        try:
            self.websocket.close()
        except Exception as exc:
            log.error(f"Error closing WebSocket: {exc}")
        finally:
            try:
                del self.connections[self.websocket]
            except KeyError:
                pass
            log.info(f"WebSocket connection closed from {self.websocket.remote_address}")


# ---------------------------------------------------------------------------
# Motion detection
# ---------------------------------------------------------------------------
def detect_motion(prev_frame: np.ndarray, curr_frame: np.ndarray) -> None:
    """Detect motion between two NumPy frames using OpenCV."""
    if prev_frame is None or curr_frame is None:
        return

    try:
        diff = cv2.absdiff(prev_frame, curr_frame)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
        contours, _ = cv2.findContours(
            thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE
        )

        for contour in contours:
            if cv2.contourArea(contour) > 100:
                x, y, w, h = cv2.boundingRect(contour)
                cv2.rectangle(curr_frame, (x, y), (x + w, y + h), (0, 0, 255), 2)
    except Exception as exc:
        log.error(f"Motion detection error: {exc}")


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
def _signal_handler(signum, frame) -> None:
    log.info(f"Signal {signum} received; initiating shutdown.")
    _shutdown.set()


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    global _camera

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _camera = Camera(
        framerate=DEFAULT_FRAMERATE,
        resolution=DEFAULT_RESOLUTION,
        low_resolution=LOW_RESOLUTION,
        detect_motion_function=detect_motion,
    )
    _camera.start()

    try:
        while not _shutdown.is_set():
            _shutdown.wait(1.0)
    except Exception as exc:
        log.error(f"Main loop error: {exc}\n{traceback.format_exc()}")
    finally:
        _camera.stop()


if __name__ == "__main__":
    main()

