import time
import threading
import signal
import sys
import smbus2
import RPi.GPIO as GPIO

# LCD constants
LCD_I2C_ADDR = 0x27
LCD_WIDTH = 16
LCD_CHR = True
LCD_CMD = False
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0b00000100
E_PULSE = 0.0005
E_DELAY = 0.0005

# GPIO pin assignments
LED_PINS = [17, 18, 23, 27, 22]

# Global state
running = True
bus = None
lcd_lock = threading.Lock()


class LCD:
    def __init__(self, bus_num=1, addr=LCD_I2C_ADDR):
        self.addr = addr
        self.bus = smbus2.SMBus(bus_num)
        self._init_lcd()

    def _write_byte(self, bits, mode):
        try:
            self.bus.write_byte(self.addr, mode | (bits & 0xF0) | LCD_BACKLIGHT)
            time.sleep(E_DELAY)
            self.bus.write_byte(self.addr, mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT)
            time.sleep(E_DELAY)
        except OSError as e:
            print(f"LCD write error: {e}", file=sys.stderr)
            raise

    def _init_lcd(self):
        time.sleep(0.05)
        self._write_byte(0x33, LCD_CMD)
        self._write_byte(0x32, LCD_CMD)
        self._write_byte(0x06, LCD_CMD)
        self._write_byte(0x0C, LCD_CMD)
        self._write_byte(0x28, LCD_CMD)
        self._write_byte(0x01, LCD_CMD)
        time.sleep(E_DELAY)

    def clear(self):
        self._write_byte(0x01, LCD_CMD)
        time.sleep(E_DELAY)

    def write_string(self, message, line):
        message = message.ljust(LCD_WIDTH)[:LCD_WIDTH]
        self._write_byte(line, LCD_CMD)
        for char in message:
            self._write_byte(ord(char), LCD_CHR)

    def close(self):
        try:
            self.clear()
            self.bus.close()
        except Exception:
            pass


class CPUStats:
    def __init__(self, bus_num=1):
        self.bus = smbus2.SMBus(bus_num)
        self.cpu_temp_offset = 0.0

    def get_cpu_temp(self):
        try:
            temp_raw = self.bus.read_word_data(0x48, 0xFA)
            temp_c = (temp_raw * 0.25) - 273.15 + self.cpu_temp_offset
            return temp_c
        except OSError as e:
            print(f"Temperature read error: {e}", file=sys.stderr)
            return None

    def get_cpu_usage(self):
        try:
            cpu_usage = self.bus.read_word_data(0x48, 0xFC)
            return cpu_usage
        except OSError as e:
            print(f"CPU usage read error: {e}", file=sys.stderr)
            return None

    def close(self):
        try:
            self.bus.close()
        except Exception:
            pass


class LEDIndicator:
    def __init__(self, led_pins):
        self.led_pins = led_pins
        GPIO.setmode(GPIO.BCM)
        for pin in self.led_pins:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

    def activate_led(self, cls):
        if 0 <= cls <= 4:
            GPIO.output(self.led_pins[cls], GPIO.HIGH)
        else:
            print(f"Invalid class index: {cls}", file=sys.stderr)

    def deactivate_led(self, cls):
        if 0 <= cls <= 4:
            GPIO.output(self.led_pins[cls], GPIO.LOW)
        else:
            print(f"Invalid class index: {cls}", file=sys.stderr)

    def cleanup(self):
        for pin in self.led_pins:
            GPIO.output(pin, GPIO.LOW)
        GPIO.cleanup()


def update_lcd(lcd, cpu_stats, led_indicator):
    global running
    while running:
        cpu_usage = cpu_stats.get_cpu_usage()
        cpu_temp = cpu_stats.get_cpu_temp()

        if cpu_usage is not None and cpu_temp is not None:
            with lcd_lock:
                lcd.write_string(f"CPU: {cpu_usage}%", LCD_LINE_1)
                lcd.write_string(f"Temp: {cpu_temp:.1f}C", LCD_LINE_2)
        else:
            with lcd_lock:
                lcd.write_string("Sensor Error", LCD_LINE_1)
                lcd.write_string("Check wiring", LCD_LINE_2)

        time.sleep(1)


def activate_led_for_class(led_indicator, cls):
    global running
    if not running:
        return
    led_indicator.activate_led(cls)
    time.sleep(1)
    led_indicator.deactivate_led(cls)


def signal_handler(sig, frame):
    global running
    running = False


def main():
    global bus, running

    signal.signal(signal.SIGINT, signal_handler)

    try:
        bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Failed to initialize I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        lcd = LCD(bus_num=1)
    except Exception as e:
        print(f"Failed to initialize LCD: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        cpu_stats = CPUStats(bus_num=1)
    except Exception as e:
        print(f"Failed to initialize CPU stats: {e}", file=sys.stderr)
        lcd.close()
        bus.close()
        sys.exit(1)

    try:
        led_indicator = LEDIndicator(LED_PINS)
    except Exception as e:
        print(f"Failed to initialize LED indicator: {e}", file=sys.stderr)
        lcd.close()
        cpu_stats.close()
        bus.close()
        sys.exit(1)

    lcd_thread = threading.Thread(target=update_lcd, args=(lcd, cpu_stats, led_indicator), daemon=True)
    lcd_thread.start()

    try:
        while running:
            for cls in range(5):
                if not running:
                    break
                activate_led_for_class(led_indicator, cls)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        running = False
        lcd.clear()
        lcd.close()
        cpu_stats.close()
        led_indicator.cleanup()
        if bus:
            bus.close()


if __name__ == "__main__":
    main()

