oled_display = adafruit_ssd1306.SSD1306_I2C(128, 64, i2c_bus)

# Initialize DHT22 sensor on GPIO4 (board.D4, BCM)
dht_sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    running = False

def read_sensor_data():
    """Reads temperature and humidity from the DHT22 sensor with retry mechanism."""
    for attempt in range(3):
        try:
            temperature = dht_sensor.temperature
            humidity = dht_sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                raise RuntimeError("Sensor returned None values")
        except RuntimeError as e:
            print(f"Sensor read attempt {attempt + 1} failed: {e}")
            time.sleep(2)
        except Exception as e:
            print(f"Unexpected error during sensor read: {e}")
            break
    return None, None

def display_data(temperature, humidity):
