import json
import random
import signal
import sys
import time
from threading import Event

import paho.mqtt.client as mqtt

BROKER = "test.mosquitto.org"
PORT = 1883
TOPIC = "classroom/temperature"
KEEPALIVE = 60
READINGS = 5
DELAY = 2.0
RETRY_DELAY = 2.0
MAX_RETRIES = 3

shutdown_event = Event()


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
    else:
        print(f"Connection failed with reason code: {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    if reason_code != 0:
        print(f"Publish failed for message ID: {mid} with reason code: {reason_code}")


def generate_reading():
    return round(random.uniform(19.00, 26.00), 2)


def main():
    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    client.on_connect = on_connect
    client.on_publish = on_publish

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            client.connect(BROKER, PORT, KEEPALIVE)
            break
        except Exception as e:
            print(f"Connection attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)

    if not client.is_connected():
        print("Failed to connect to MQTT broker after multiple attempts.")
        sys.exit(1)

    client.loop_start()

    try:
        for i in range(READINGS):
            if shutdown_event.is_set():
                break

            payload = json.dumps({"temperature": generate_reading(), "index": i})
            info = client.publish(TOPIC, payload, qos=1)
            info.wait_for_publish(timeout=5)

            if info.rc != mqtt.MQTT_ERR_SUCCESS:
                print(f"Publish attempt {i + 1} failed with rc={info.rc}")
            else:
                print(f"Published reading {i + 1}: {payload}")

            if i < READINGS - 1 and not shutdown_event.is_set():
                shutdown_event.wait(DELAY)

        if shutdown_event.is_set():
            print("Shutdown requested; aborting publish loop.")
        else:
            print(f"Published {READINGS} messages successfully.")

    except Exception as e:
        print(f"Unexpected error during publish: {e}")
    finally:
        client.loop_stop()
        client.disconnect()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, lambda s, f: shutdown_event.set())
    signal.signal(signal.SIGTERM, lambda s, f: shutdown_event.set())
    main()

