import time
import board
import busio
import adafruit_bme280
import adafruit_tsl2591

# Constants
I2C_ADDRESS_BME280 = 0x76
I2C_ADDRESS_TSL2591 = 0x29
MULTIPLEXER_ADDRESS = 0x77
READ_INTERVAL = 2  # seconds

# Global resources for cleanup
i2c_bus = None
bme280_sensor = None
tsl2591_sensor = None

def initialize_i2c():
    """Initializes the I2C bus on board.SCL and board.SDA."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        print("I2C bus initialized successfully.")
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False

def initialize_multiplexer():
    """Initializes the TCA9548A I2C multiplexer."""
    global i2c_bus
    try:
        i2c_bus.writeto(MULTIPLEXER_ADDRESS, bytearray([0x00]))  # Select default address
        print("Multiplexer initialized successfully.")
        return True
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return False

def initialize_sensors():
    """Initializes the BME280 and TSL2591 sensors."""
    global bme280_sensor, tsl2591_sensor
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=I2C_ADDRESS_BME280)
        tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_bus, address=I2C_ADDRESS_TSL2591)
        print("Sensors initialized successfully.")
        return True
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        return False

def read_sensor_data(sensor_type):
    """Reads data from the specified sensor type."""
    if sensor_type == "bme280":
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
            return temperature, humidity
        except Exception as e:
            print(f"Error reading BME280 data: {e}")
            return None, None
    elif sensor_type == "tsl2591":
        try:
            light_intensity = tsl2591_sensor.lux
            return light_intensity
        except Exception as e:
            print(f"Error reading TSL2591 data: {e}")
            return None

def display_sensor_data(temperature, humidity, light_intensity):
    """Displays the sensor data on the console."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")
    else:
        print("Failed to read sensor data.")

def cleanup():
    """Releases all resources."""
    global i2c_bus, bme280_sensor, tsl2591_sensor
    print("Cleaning up resources...")
    if bme280_sensor:
        try:
            bme280_sensor.exit()
        except Exception:
            pass
    if tsl2591_sensor:
        try:
            tsl2591_sensor.exit()
        except Exception:
            pass
    if i2c_bus:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
    print("Cleanup complete.")

def main():
    """Main function to read and display sensor data."""
    global i2c_bus, bme280_sensor, tsl2591_sensor

    if not initialize_i2c():
        return

    if not initialize_multiplexer():
        cleanup()
        return

    if not initialize_sensors():
        cleanup()
        return

    print("Starting sensor data acquisition. Press Ctrl+C to stop.")

    try:
        while True:
            temperature, humidity = read_sensor_data("bme280")
            light_intensity = read_sensor_data("tsl2591")
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

