import time
import sys

try:
    from gpiozero import CPUTemperature
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)


def read_cpu_temperature():
    """
    Reads the CPU temperature from the on-board sensor.

    Returns:
        float: The CPU temperature in degrees Celsius, or None if an error occurs.
    """
    try:
        cpu_temp = CPUTemperature()
        return cpu_temp.temperature
    except FileNotFoundError:
        print("Error: CPU temperature sensor not found. Ensure the kernel is running.", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None


def main():
    """
    Main function to continuously read and print CPU temperature.
    """
    try:
        while True:
            cpu_temp = read_cpu_temperature()

            if cpu_temp is not None:
                print(f"CPU Temperature: {cpu_temp:.2f} °C")
            else:
                print("Failed to read CPU temperature. Retrying in 5 seconds...", file=sys.stderr)

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram terminated")
        sys.exit(0)


if __name__ == "__main__":
    main()

