import serial
import time
import csv
import sys

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1
LOG_FILE = 'temperature_log.csv'

def open_uart():
    """Open the UART port with error handling."""
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error opening UART port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

def read_temperature(uart):
    """Read a temperature line from the UART. Returns None on timeout."""
    try:
        raw = uart.readline()
    except serial.SerialException as e:
        print(f"Error reading from UART: {e}", file=sys.stderr)
        return None

    if not raw:
        return None

