import time
import logging
import signal
import sys
import paho.mqtt.client as mqtt
from gpiozero import DHT22
from gpiozero.exc import BadPinFactory

import config

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

running = True
client = None
dht_device = None

def signal_handler(sig, frame):
    global running
    logger.info(f"Signal {sig} received, shutting down...")
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker")
        client.subscribe(f"homie/{config.homieclientid}/$state")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker, reason code: {reason_code}")

def on_message(client, userdata, msg):
    global running
    try:
        payload = msg.payload.decode('utf-8').strip().lower()
        if msg.topic == f"homie/{config.homieclientid}/$state" and payload == "disconnected":
            logger.warning("MQTT broker disconnected, attempting to reconnect...")
            running = False
    except Exception as e:
        logger.error(f"Error processing MQTT message: {e}")

def publish_homie_discovery():
    global client
    try:
        client.publish(f"homie/{config.homieclientid}/$state", "init")
        client.publish(f"homie/{config.homieclientid}/$homie", "4.0")
        client.publish(f"homie/{config.homieclientid}/$name", config.homieclientname)
        client.publish(f"homie/{config.homieclientid}/$nodes", config.homienodes)

        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$name", "DHT22 Sensor")
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$properties", "temperature,humidity")

        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature/$name", "Temperature")
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature/$unit", "°C")
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature/$datatype", "float")

        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity/$name", "Humidity")
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity/$unit", "%")
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity/$datatype", "float")

        client.publish(f"homie/{config.homieclientid}/$state", "ready")
        logger.info("Homie discovery published")
    except Exception as e:
        logger.error(f"Error publishing Homie discovery: {e}")

def read_dht22():
    global dht_device
    if dht_device is None:
        logger.error("DHT22 device not initialized")
        return None, None
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logger.warning(f"DHT22 returned None on attempt {attempt+1}")
        except RuntimeError as e:
            logger.warning(f"DHT22 read error on attempt {attempt+1}: {e}")
        except Exception as e:
            logger.error(f"Unexpected DHT22 error on attempt {attempt+1}: {e}")
        time.sleep(2)
    logger.error("Failed to read DHT22 after 3 attempts")
    return None, None

def main():
    global client, dht_device, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dht_device = DHT22(config.dhtegpiopin)
        logger.info(f"DHT22 initialized on GPIO {config.dhtegpiopin}")
    except BadPinFactory as e:
        logger.error(f"GPIO pin factory error: {e}")
        sys.exit(1)
    except Exception as e:
        logger.error(f"Failed to initialize DHT22: {e}")
        sys.exit(1)

    try:
        client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            clean_session=True
        )
        client.on_connect = on_connect
        client.on_disconnect = on_disconnect
        client.on_message = on_message

        if config.mqttusername and config.mqttpassword:
            client.username_pw_set(config.mqttusername, config.mqttpassword)

        client.connect(config.mqttbroker, config.mqttport, keepalive=60)
        client.loop_start()

        publish_homie_discovery()

        while running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                try:
                    client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature", f"{temperature:.1f}")
                    client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity", f"{humidity:.1f}")
                    logger.info(f"Published: Temperature={temperature:.1f}°C, Humidity={humidity:.1f}%")
                except Exception as e:
                    logger.error(f"Error publishing sensor data: {e}")
            else:
                logger.warning("Skipping publish due to read failure")

            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        if client:
            try:
                client.loop_stop()
                client.disconnect()
                logger.info("Disconnected from MQTT broker")
            except Exception as e:
                logger.error(f"Error disconnecting MQTT: {e}")
        if dht_device:
            try:
                dht_device.close()
                logger.info("DHT22 device closed")
            except Exception as e:
                logger.error(f"Error closing DHT22: {e}")
        logger.info("Program terminated")

if __name__ == "__main__":
    main()

