import adafruit_dht

# Initialize the DHT11 sensor on board.D4 (BCM, physical pin 7)
try:
    dht_device = adafruit_dht.DHT11(board.D4, use_pulseio=False)
except Exception as e:
    print(f"Failed to initialize DHT11 sensor on board.D4: {e}")
    raise SystemExit(1)

try:
    while True:
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C")
                print(f"Humidity: {humidity:.1f} %")
            else:
                print("Failed to retrieve valid data from DHT11 sensor.")

        except RuntimeError as e:
            # DHT sensors often throw transient read errors; retry on next cycle
            print(f"DHT11 read error: {e}")

        except Exception as e:
            # Catch any other unexpected errors
            print(f"Unexpected error reading DHT11 sensor: {e}")

        time.sleep(5)

except KeyboardInterrupt:
    print("\nProgram terminated by user.")

finally:
    # Clean up the sensor resource on all exit paths
    try:
        dht_device.exit()
    except Exception:
        pass

