import board
import busio
import adafruit_bme680

LOG_FILE = "air_quality_log.txt"
READ_INTERVAL = 10

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_data(log_file, timestamp, temperature, humidity, pressure, gas):
    try:
        with open(log_file, "a") as f:
            f.write(f"{timestamp},{temperature:.2f},{humidity:.2f},{pressure:.2f},{gas:.2f}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c = None
    bme680 = None

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        bme680 = adafruit_bme680.Adafruit_BME680_I2C(i2c, address=0x77)
        bme680.sea_level_pressure = 1013.25
    except Exception as e:
        print(f"Failed to initialize BME680 sensor: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                temperature = bme680.temperature
                humidity = bme680.humidity
                pressure = bme680.pressure
                gas = bme680.gas

                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                log_data(LOG_FILE, timestamp, temperature, humidity, pressure, gas)
                print(f"Timestamp: {timestamp}, Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%, Pressure: {pressure:.2f} hPa, Gas: {gas:.2f} ohm")

                for _ in range(READ_INTERVAL):
                    if not running:
                        break
                    time.sleep(1)

            except Exception as e:
                print(f"Error reading sensor data: {e}")
                for _ in range(READ_INTERVAL):
                    if not running:
                        break
                    time.sleep(1)

    finally:
        if bme680 is not None:
            try:
                bme680.exit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

