import time
import logging
import signal
import sys
from typing import Optional, Tuple

try:
    import smbus2 as smbus
except ImportError:
    smbus = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor on Raspberry Pi."""

    REG_STATUS = 0x00
    REG_DATA = 0x01
    REG_CONFIG = 0x02
    REG_ID = 0x03

    STATUS_MEASURE_MASK = 0x80
    STATUS_MEASURE_READY = 0x00
    STATUS_MEASURE_BUSY = 0x80

    CONFIG_RESET = 0x00
    CONFIG_MEASURE_1S = 0x01
    CONFIG_MEASURE_2S = 0x02
    CONFIG_MEASURE_4S = 0x03
    CONFIG_MEASURE_8S = 0x04
    CONFIG_MEASURE_16S = 0x05
    CONFIG_MEASURE_32S = 0x06
    CONFIG_MEASURE_64S = 0x07
    CONFIG_MEASURE_128S = 0x08
    CONFIG_MEASURE_256S = 0x09
    CONFIG_MEASURE_512S = 0x0A
    CONFIG_MEASURE_1024S = 0x0B

    def __init__(self, bus: int = 1, address: int = 0x58):
        if smbus is None:
            raise RuntimeError("smbus2 is not installed; install with: pip install smbus2")
        self.address = address
        self.bus = smbus.SMBus(bus)
        self._closed = False

    # ------------------------------------------------------------------
    # Low-level I2C helpers
    # ------------------------------------------------------------------
    def _write_register(self, register: int, value: int) -> None:
        if self._closed:
            raise RuntimeError("I2C bus is closed")
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as exc:
            logger.error("I2C write to register 0x%02X failed: %s", register, exc)
            raise

    def _read_register(self, register: int, length: int = 1) -> bytes:
        if self._closed:
            raise RuntimeError("I2C bus is closed")
        try:
            return self.bus.read_i2c_block_data(self.address, register, length)
        except OSError as exc:
            logger.error("I2C read from register 0x%02X failed: %s", register, exc)
            raise

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def begin(self) -> bool:
        """Power-on the sensor and wait for it to stabilise."""
        try:
            self._write_register(self.REG_CONFIG, self.CONFIG_RESET)
