import signal
import sys
import time

import RPi.GPIO as GPIO

FAN_PIN = 17
PWM_FREQUENCY = 25  # Hz
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"
TEMP_THRESHOLD = 25.0  # °C
HYSTERESIS = 1.0       # °C
SLEEP_INTERVAL = 1.0   # seconds

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def get_cpu_temperature():
    """Return CPU temperature in °C, or None on error."""
    try:
        with open(TEMP_FILE, "r") as f:
            raw = f.read().strip()
        return float(raw) / 1000.0
    except (OSError, ValueError) as exc:
        print(f"[ERROR] Failed to read CPU temperature: {exc}", file=sys.stderr)
        return None


def set_fan_speed(pwm, speed):
    """Set fan speed (0.0–1.0) and log the change."""
    try:
        pwm.ChangeDutyCycle(speed * 100.0)
        print(f"[INFO] Fan speed set to {speed * 100:.0f}%")
    except Exception as exc:
        print(f"[ERROR] Failed to set fan speed: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize GPIO {FAN_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    pwm = None
    try:
        pwm = GPIO.PWM(FAN_PIN, PWM_FREQUENCY)
        pwm.start(0.0)

        last_speed = 0.0

        while _running:
            temp = get_cpu_temperature()
            if temp is None:
                time.sleep(SLEEP_INTERVAL)
                continue

            if temp > TEMP_THRESHOLD + HYSTERESIS:
                speed = 1.0
            elif temp < TEMP_THRESHOLD - HYSTERESIS:
                speed = 0.0
            else:
                speed = last_speed

            if speed != last_speed:
                set_fan_speed(pwm, speed)
                last_speed = speed

            time.sleep(SLEEP_INTERVAL)

    except Exception as exc:
        print(f"[ERROR] Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        GPIO.cleanup()
        print("[INFO] GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

