import signal
import sys
import time
import logging

import ina219

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("ina219_ups")

SUPPLY_SHUNT = 0.00725
BATTERY_SHUNT = 0.005
SAMPLE_INTERVAL = 2.0
NUM_BYTES = 42

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def read_ina219(ina, shunt):
    try:
        voltage = ina.voltage()
        current = ina.current()
        if voltage is None or current is None:
            raise RuntimeError("INA219 returned None for voltage or current.")
        return voltage, current
    except Exception as exc:
        log.error("INA219 read failed: %s", exc)
        return None, None


def read_ups(ups):
    try:
        proc_mv = ups.read_bus_voltage()
        batt_mv = ups.read_battery_voltage()
        temp_c = ups.read_temperature()
        capacity = ups.read_battery_percent()
        if proc_mv is None or batt_mv is None or temp_c is None or capacity is None:
            raise RuntimeError("UPS returned None for one or more values.")
        return proc_mv, batt_mv, temp_c, capacity
    except Exception as exc:
        log.error("UPS read failed: %s", exc)
        return None, None, None, None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ina_supply = ina219.INA219(
            busnum=1,
            address=0x40,
            shunt_resistance=SUPPLY_SHUNT,
            bus_voltage=3.3,
        )
        ina_battery = ina219.INA219(
            busnum=1,
            address=0x41,
            shunt_resistance=BATTERY_SHUNT,
            bus_voltage=3.3,
        )
    except Exception as exc:
        log.error("Failed to initialise INA219 devices: %s", exc)
        sys.exit(1)

    try:
        ups = ina219.INA219(
            busnum=1,
            address=0x34,
            bus_voltage=3.3,
        )
    except Exception as exc:
        log.error("Failed to initialise UPS device: %s", exc)
        ups = None

    log.info("INA219 devices initialised (supply=0.00725 Ω, battery=0.005 Ω).")

    try:
        while _running:
            supply_v, supply_a = read_ina219(ina_supply, SUPPLY_SHUNT)
            battery_v, battery_a = read_ina219(ina_battery, BATTERY_SHUNT)
            ups_proc, ups_batt, ups_temp, ups_cap = read_ups(ups)

            if supply_v is not None and supply_a is not None:
                print(f"Supply: {supply_v:.3f} V, {supply_a:.3f} mA")
            if battery_v is not None and battery_a is not None:
                print(f"Battery: {battery_v:.3f} V, {battery_a:.3f} mA")
            if ups_proc is not None and ups_batt is not None and ups_temp is not None and ups_cap is not None:
                print(
                    f"UPS: Proc {ups_proc:.0f} mV, Battery Port {ups_batt:.0f} mV, "
                    f"Temp {ups_temp:.1f} C, Capacity {ups_cap:.1f} %"
                )

            for _ in range(int(SAMPLE_INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        try:
            ina_supply.close()
        except Exception:
            pass
        try:
            ina_battery.close()
        except Exception:
            pass
        try:
            ups.close()
        except Exception:
            pass
        log.info("Resources released. Exiting.")


if __name__ == "__main__":
    main()

