THINGSPEAK_CHANNEL_ID = 1234567
THINGSPEAK_API_KEY = "YOUR_API_KEY"
LOG_FILE = "temperature.txt"
ERROR_LOG_FILE = "error.log"
READ_INTERVAL = 60  # seconds
READ_TIMEOUT = 2  # seconds

# Global flag for graceful shutdown
running = True

def signal_handler(signum, frame):
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False

def log_error(message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}")

def read_temperature(sensor):
    """Reads temperature from DHT22 sensor with retry logic."""
    for attempt in range(3):
        try:
            temperature = sensor.temperature
            if temperature is not None:
                return temperature
            else:
                log_error(f"DHT22 returned None on attempt {attempt+1}")
        except RuntimeError as e:
            log_error(f"DHT22 read error on attempt {attempt+1}: {e}")
        except Exception as e:
            log_error(f"Unexpected DHT22 error on attempt {attempt+1}: {e}")
        time.sleep(2)
    return None

def upload_to_thingspeak(temperature):
    """Uploads temperature data to ThingSpeak."""
    try:
        url = f"https://api.thingspeak.com/update?api_key={THINGSPEAK_API_KEY}&field1={temperature:.2f}"
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        print(f"Temperature uploaded to ThingSpeak. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        log_error(f"Error uploading to ThingSpeak: {e}")

def main():
    global running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DHT22 sensor
    try:
        import adafruit_dht
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        print("DHT22 sensor initialized on GPIO4.")
    except Exception as e:
        log_error(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    # Main loop
    try:
        while running:
            temperature = read_temperature(sensor)

            if temperature is not None:
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_entry = f"{timestamp}, Temperature: {temperature:.2f} C"
                print(log_entry)

                try:
                    with open(LOG_FILE, "a") as f:
                        f.write(log_entry + "\n")
                except Exception as e:
                    log_error(f"Failed to write to log file: {e}")

                upload_to_thingspeak(temperature)
            else:
                log_error("Failed to read temperature after multiple attempts.")

            # Wait for next reading, checking running flag periodically
            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
    finally:
        # Cleanup
        try:
            sensor.exit()
            print("DHT22 sensor resources released.")
        except Exception as e:
            log_error(f"Error releasing sensor resources: {e}")
        print("Program terminated.")

if __name__ == "__main__":
    main()

