import signal
import sys
import time

import board
import busio
from adafruit_fan_hitec import HITEC128

FAN_PIN = board.D18
PWM_FREQUENCY = 1000
TEMP_THRESHOLD = 40.0
DUTY_CYCLE_HIGH = 100.0
DUTY_CYCLE_LOW = 20.0
READ_INTERVAL = 5.0

_running = True
_fan = None


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _fan

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Failed to initialize I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _fan = HITEC128(i2c, FAN_PIN)
    except Exception as exc:
        print(f"Failed to initialize HITEC128 fan on GPIO18: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _fan.frequency = PWM_FREQUENCY
    except Exception as exc:
        print(f"Failed to set PWM frequency: {exc}", file=sys.stderr)
        sys.exit(1)

    print("Fan control started. Press Ctrl+C to exit.")

    try:
        while _running:
            try:
                temperature = _fan.temperature
            except Exception as exc:
                print(f"Temperature read failed: {exc}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if temperature > TEMP_THRESHOLD:
                duty_cycle = DUTY_CYCLE_HIGH
            else:
                duty_cycle = DUTY_CYCLE_LOW

            try:
                _fan.duty_cycle = duty_cycle / 100.0
            except Exception as exc:
                print(f"Failed to set fan duty cycle: {exc}", file=sys.stderr)

            time.sleep(READ_INTERVAL)
    finally:
        if _fan is not None:
            try:
                _fan.duty_cycle = 0.0
            except Exception:
                pass
        print("Fan control stopped.")


if __name__ == "__main__":
    main()

