import signal
import sys
import time

import RPi.GPIO as GPIO

SENSOR_PINS = {1: 17, 2: 27, 3: 22}
POLL_INTERVAL = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for sensor_id, pin in SENSOR_PINS.items():
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as exc:
            print(f"Error: failed to configure GPIO{pin} (sensor {sensor_id}): {exc}", file=sys.stderr)
            GPIO.cleanup()
            return False
    return True


def read_sensor(sensor_id):
    pin = SENSOR_PINS.get(sensor_id)
    if pin is None:
        return None
    try:
        return GPIO.input(pin)
    except Exception as exc:
        print(f"Error: failed to read GPIO{pin} (sensor {sensor_id}): {exc}", file=sys.stderr)
        return None


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if not setup_gpio():
        sys.exit(1)

    print("GPIO initialized. Monitoring sensors 1, 2, 3 every 1 second.")
    print(f"Pins: {SENSOR_PINS}")
    print(f"Poll interval: {POLL_INTERVAL:.1f} s")

    try:
        while _running:
            sensor1 = read_sensor(1)
            sensor2 = read_sensor(2)
            sensor3 = read_sensor(3)

            if sensor1 is not None:
                print("Response for sensor 1")
            if sensor2 is not None:
                print("Response for sensor 2")
            if sensor3 is not None:
                print("Response for sensor 3")

            time.sleep(POLL_INTERVAL)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

