import time
import signal
import sys
import threading

try:
    import DOG
except ImportError:
    print("Error: DOG library not found. Install with: pip install DOG")
    sys.exit(1)

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    global running
    print("\nShutdown signal received. Cleaning up...")
    running = False

def log_data(filename, data):
    """Logs data to a file with a newline."""
    try:
        with open(filename, "a") as f:
            f.write(data + "\n")
    except IOError as e:
        print(f"Error writing to file: {e}")

def display_data(filename):
    """Displays the contents of the log file."""
    try:
        with open(filename, "r") as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Error: File not found: {filename}")
    except IOError as e:
        print(f"Error reading from file: {e}")

def send_data(data):
    """Sends data to the DOG device."""
    try:
        DOG.send(data)
    except Exception as e:
        print(f"Error sending data: {e}")

def write_data(filename, data):
    """Writes data directly to the log file."""
    log_data(filename, data)

def help_command(command=None):
    """Displays help information for a specific command."""
    if command == "start":
        print("Usage: start <filename>")
        print("Starts logging data to the specified file.")
    elif command == "stop":
        print("Usage: stop")
        print("Stops the data logging process.")
    elif command == "help":
        print("Usage: help [command]")
        print("Displays help information for a specific command.")
    elif command == "display":
        print("Usage: display")
        print("Displays the contents of the log file.")
    elif command == "send":
        print("Usage: send <data>")
        print("Sends data to the DOG device.")
    elif command == "write":
        print("Usage: write <data>")
        print("Writes data directly to the log file.")
    elif command == "exit":
        print("Usage: exit")
        print("Stops the DOG library and exits the program.")
    else:
        print("Available commands:")
        print("  start <filename>")
        print("  stop")
        print("  help [command]")
        print("  display")
        print("  send <data>")
        print("  write <data>")
        print("  exit")

def main():
    """Main function to run the DOG data logging program."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DOG library
    try:
        DOG.init()
    except Exception as e:
        print(f"Error initializing DOG library: {e}")
        sys.exit(1)

    # Flag to indicate if the library's API call has been started
    api_call_started = False

    # Thread to handle data logging
    data_logging_thread = None

    try:
        while running:
            try:
                command = input("DOG> ").strip()

                if not command:
                    continue

                parts = command.split()
                command = parts[0].lower()

                if command == "start":
                    if not api_call_started:
                        filename = parts[1]
                        if not filename:
                            print("Error: Filename is required.")
                            continue

                        # Start the data logging thread
                        data_logging_thread = threading.Thread(
                            target=lambda: DOG.receive(log_data, filename),
                            daemon=True
                        )
                        data_logging_thread.start()
                        api_call_started = True
                        print(f"Logging started to {filename}")
                    else:
                        print("Error: API call already started.")

                elif command == "stop":
                    if api_call_started:
                        try:
                            DOG.stop()
                        except Exception as e:
                            print(f"Error stopping DOG library: {e}")
                        api_call_started = False
                        print("Logging stopped.")
                    else:
                        print("Error: API call not started.")

                elif command == "help":
                    if len(parts) == 1:
                        help_command()
                    else:
                        help_command(parts[1])

                elif command == "display":
                    if api_call_started:
                        display_data(parts[1] if len(parts) > 1 else "log.txt")
                    else:
                        print("Error: API call not started.")

                elif command == "send":
                    if api_call_started:
                        send_data(" ".join(parts[1:]))
                    else:
                        print("Error: API call not started.")

                elif command == "write":
                    if api_call_started:
                        write_data(parts[1] if len(parts) > 1 else "log.txt", " ".join(parts[2:]))
                    else:
                        print("Error: API call not started.")

                elif command == "exit":
                    if api_call_started:
                        try:
                            DOG.stop()
                        except Exception:
                            pass
                    print("Exiting...")
                    break

                else:
                    print("Invalid command. Type 'help' for available commands.")

            except Exception as e:
                print(f"An unexpected error occurred: {e}")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        # Ensure the library's API call is invoked on every exit path
        if api_call_started:
            try:
                DOG.stop()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

