                            print("Error: Filename is required.")
                            continue

                        # Start the data logging thread
                        data_logging_thread = threading.Thread(
                            target=lambda: DOG.receive(log_data, filename),
                            daemon=True
                        )
                        data_logging_thread.start()
                        api_call_started = True
                        print(f"Logging started to {filename}")
                    else:
                        print("Error: API call already started.")

                elif command == "stop":
                    if api_call_started:
                        try:
                            DOG.stop()
                        except Exception as e:
                            print(f"Error stopping DOG library: {e}")
                        api_call_started = False
                        print("Logging stopped.")
                    else:
                        print("Error: API call not started.")

                elif command == "help":
                    if len(parts) == 1:
                        help_command()
                    else:
                        help_command(parts[1])

                elif command == "display":
                    if api_call_started:
                        display_data(parts[1] if len(parts) > 1 else "log.txt")
                    else:
                        print("Error: API call not started.")

                elif command == "send":
                    if api_call_started:
                        send_data(" ".join(parts[1:]))
                    else:
                        print("Error: API call not started.")

                elif command == "write":
                    if api_call_started:
                        write_data(parts[1] if len(parts) > 1 else "log.txt", " ".join(parts[2:]))
                    else:
                        print("Error: API call not started.")

                elif command == "exit":
                    if api_call_started:
                        try:
                            DOG.stop()
                        except Exception:
                            pass
                    print("Exiting...")
                    break

                else:
                    print("Invalid command. Type 'help' for available commands.")

            except Exception as e:
                print(f"An unexpected error occurred: {e}")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        # Ensure the library's API call is invoked on every exit path
        if api_call_started:
            try:
                DOG.stop()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

