    sys.exit(1)

BUTTON_PIN = 4
LED_PIN = 17
POLL_DELAY = 0.1

button = None
led = None
running = True


def cleanup():
    """Release GPIO resources cleanly."""
    global button, led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None


def handle_signal(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    global running
    running = False


def main():
    global button, led

    # Register signal handlers for clean termination
    signal.signal(signal.SIGTERM, handle_signal)
    signal.signal(signal.SIGINT, handle_signal)

    try:
        # Initialize button with internal pull-down and LED
        button = Button(BUTTON_PIN, pull_up=False)
        led = LED(LED_PIN)

        print("Button-controlled LED started. Press Ctrl+C to exit.")

        while running:
            # gpiozero Button.is_pressed returns True when the pin is LOW
            if button.is_pressed:
                led.on()
            else:
                led.off()

            time.sleep(POLL_DELAY)

    except GPIOZeroError as e:
        print(f"GPIO error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

