import logging
import signal
import sys
import time
from typing import Callable, Optional

import zmq

try:
    import board
    import busio
    from adafruit_motor import pwmout
    from gpiozero import PWMOutputDevice, DigitalOutputDevice
except ImportError:
    logging.error("Required libraries not found. Install with: pip install adafruit-circuitpython-motor gpiozero zmq")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class PIDHandler:
    """
    A class to manage PID control and error output signals using a Raspberry Pi.
    """

    def __init__(self, pwm_pin: int = 12, digital_pin: int = 10, pwm_frequency: int = 1000,
                 pwm_initial_duty_cycle: float = 0.0, watchdog_timeout: int = 20,
                 error_callback: Optional[Callable[[float], None]] = None,
                 message_callback: Optional[Callable[[str], None]] = None):
        self.pwm_pin = pwm_pin
        self.digital_pin = digital_pin
        self.pwm_frequency = pwm_frequency
        self.pwm_initial_duty_cycle = pwm_initial_duty_cycle
        self.watchdog_timeout = watchdog_timeout
        self.error_callback = error_callback
        self.message_callback = message_callback
        self.global_err_state = 0.0
        self.last_msg = time.time()
        self.pwm_output: Optional[pwmout.PWMOutputDevice] = None
        self.digital_output: Optional[DigitalOutputDevice] = None
        self.context: Optional[zmq.Context] = None
        self.socket: Optional[zmq.Socket] = None
        self._running = True

        self._initialize_gpio()
        self._initialize_zmq()

    def _initialize_gpio(self):
        """Initializes GPIO devices using gpiozero."""
        try:
            if self.pwm_pin is not None:
                self.pwm_output = PWMOutputDevice(self.pwm_pin, frequency=self.pwm_frequency, initial_value=self.pwm_initial_duty_cycle)
                logger.info(f"PWM output initialized on GPIO {self.pwm_pin} at {self.pwm_frequency} Hz.")
            else:
                self.digital_output = DigitalOutputDevice(self.digital_pin, initial_value=False)
                logger.info(f"Digital output initialized on GPIO {self.digital_pin}.")
        except Exception as e:
            logger.error(f"Error initializing GPIO: {e}")
            self.cleanup()
            raise

    def _initialize_zmq(self):
        """Initializes ZeroMQ context and socket."""
        try:
            self.context = zmq.Context()
            self.socket = self.context.socket(zmq.SUB)
            self.socket.setsockopt(zmq.LINGER, 0)
            self.socket.connect("tcp://localhost:5555")
            logger.info("ZMQ socket connected to 'tcp://localhost:5555'.")
        except Exception as e:
            logger.error(f"Error initializing ZMQ: {e}")
            self.cleanup()
            raise

    def update_error_output(self, error_value: float) -> None:
        """Updates the error output based on the provided error value."""
        self.global_err_state = error_value
        self.set_error_output(self.global_err_state)
        if self.error_callback:
            self.error_callback(self.global_err_state)

    def set_error_output(self, state: bool) -> None:
        """Sets the error output state."""
        if self.pwm_output:
            try:
                self.pwm_output.value = state
            except Exception as e:
                logger.error(f"Error setting PWM output: {e}")
        elif self.digital_output:
            try:
                self.digital_output.value = state
            except Exception as e:
                logger.error(f"Error setting digital output: {e}")
        else:
            logger.error("No GPIO output device initialized.")

    def handle_message(self, message: str) -> None:
        """Handles incoming messages from the ZeroMQ socket."""
        self.last_msg = time.time()
        if self.message_callback:
            self.message_callback(message)

    def watchdog_check(self) -> None:
        """Checks for watchdog timeout and handles it."""
        if time.time() - self.last_msg > self.watchdog_timeout:
            logger.warning("Watchdog timeout! Resetting error output.")
            self.set_error_output(True)

    def cleanup(self) -> None:
        """Cleans up resources."""
        self._running = False
        logger.info("Cleaning up resources...")
        if self.pwm_output:
            try:
                self.pwm_output.value = 0
                self.pwm_output.close()
                logger.info("PWM output closed.")
            except Exception as e:
                logger.error(f"Error closing PWM output: {e}")
        if self.digital_output:
            try:
                self.digital_output.close()
                logger.info("Digital output closed.")
            except Exception as e:
                logger.error(f"Error closing digital output: {e}")
        if self.socket:
            try:
                self.socket.close()
                logger.info("ZMQ socket closed.")
            except Exception as e:
                logger.error(f"Error closing ZMQ socket: {e}")
        if self.context:
            try:
                self.context.term()
                logger.info("ZMQ context terminated.")
            except Exception as e:
                logger.error(f"Error terminating ZMQ context: {e}")
        logger.info("Cleanup complete.")

    def run(self) -> None:
        """Runs the PID handler loop."""
        logger.info("Starting PID handler loop...")
        try:
            while self._running:
                self.watchdog_check()
                try:
                    message = self.socket.recv(flags=zmq.NOBLOCK)
                    if message:
                        self.handle_message(message.decode())
                except zmq.Again:
                    pass
                time.sleep(0.01)
        except Exception as e:
            logger.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()


def signal_handler(signum, frame, handler: PIDHandler):
    """Handles signals for graceful shutdown."""
    logger.info(f"Signal {signum} received. Shutting down...")
    handler._running = False


if __name__ == "__main__":
    handler = PIDHandler()
    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, handler))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, handler))
    handler.run()

