import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO not available. Run on a Raspberry Pi.")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    try:
        GPIO.output(FAN_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        _cleanup()
        sys.exit(1)

    pwm = None
    try:
        pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Warning: Could not initialize hardware PWM on GPIO{FAN_PIN} at {PWM_FREQ} Hz: {e}")
        print("Falling back to software PWM.")
        pwm = None

    try:
        while _running:
            try:
                speed_str = input("Enter fan speed (0-100, or 'q' to quit): ").strip()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if speed_str.lower() == 'q':
                break

            try:
                speed = float(speed_str)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100.")
                continue

            if not 0 <= speed <= 100:
                print("Invalid input. Please enter a number between 0 and 100.")
                continue

            if pwm is not None:
                try:
                    pwm.ChangeDutyCycle(speed)
                except Exception as e:
                    print(f"Warning: Failed to set PWM duty cycle: {e}")
            else:
                print(f"Hardware PWM unavailable. Setting fan speed to {speed:.1f}%")

            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        _cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

