import atexit
import time
import logging
import signal

try:
    from adafruit_servokit import ServoKit
except ImportError:
    ServoKit = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

MIN_PULSE_WIDTH = 150
MAX_PULSE_WIDTH = 600
DEFAULT_DELAY = 0.029
SHOOT_DELAY = 0.15

SERVO_CHANNELS = {
    'claw': 0,
    'lock': 1,
    'water_gun': 2,
}

class Fuchikoma:
    def __init__(self, i2c_bus=1, pwm_frequency=60):
        if ServoKit is None:
            raise RuntimeError("adafruit-circuitpython-servokit is not installed.")
        self.kit = ServoKit(channels=16, i2c=None, address=0x40)
        self.pwm_frequency = pwm_frequency
        self.delay = DEFAULT_DELAY
        self._initialized = False
        self._running = True

        try:
            self.kit.servo[SERVO_CHANNELS['claw']].frequency = pwm_frequency
            self.kit.servo[SERVO_CHANNELS['lock']].frequency = pwm_frequency
            self.kit.servo[SERVO_CHANNELS['water_gun']].frequency = pwm_frequency
            self._initialized = True
            logger.info("PCA9685 initialized successfully on I2C bus %d at %d Hz.", i2c_bus, pwm_frequency)
        except (ValueError, OSError) as e:
            logger.error("Failed to initialize PCA9685 on I2C bus %d: %s", i2c_bus, e)
            self.cleanup()
            raise

    def _move_servo(self, channel, angle):
        if not self._initialized:
            raise RuntimeError("PCA9685 not initialized.")
        if channel not in SERVO_CHANNELS:
            raise ValueError(f"Invalid servo channel: {channel}")
        if not -77 <= angle <= 77:
            raise ValueError(f"Angle {angle} out of range for channel {channel}")

        pulse_width = self._angle_to_pulse(angle)
        self.kit.servo[SERVO_CHANNELS[channel]].angle = None
        self.kit.servo[SERVO_CHANNELS[channel]].pulse_width = pulse_width
        time.sleep(self.delay)
        self.kit.servo[SERVO_CHANNELS[channel]].duty_cycle = 0

    def _angle_to_pulse(self, angle):
        pulse_width = (angle / 77.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH
        return pulse_width

    def move_servo(self, servo_name, angle):
        if servo_name not in SERVO_CHANNELS:
            raise ValueError(f"Invalid servo name: {servo_name}")
        self._move_servo(SERVO_CHANNELS[servo_name], angle)

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(SHOOT_DELAY)

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        if not self._initialized:
            return
        self._running = False
        logger.info("Cleaning up PCA9685 channels...")
        for channel in SERVO_CHANNELS.values():
            try:
                self.kit.servo[channel].duty_cycle = 0
            except Exception as e:
                logger.error("Error setting channel %d duty cycle to zero: %s", channel, e)
        try:
            self.kit.deinit()
        except Exception as e:
            logger.error("Error deinitializing PCA9685: %s", e)
        self._initialized = False
        logger.info("PCA9685 cleanup complete.")

def signal_handler(sig, frame):
    logger.info("Signal received, shutting down...")
    raise KeyboardInterrupt

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fuchikoma = Fuchikoma(i2c_bus=1, pwm_frequency=60)
        atexit.register(fuchikoma.cleanup)

        fuchikoma.bite()
        time.sleep(1)
        fuchikoma.open_claw()
        time.sleep(1)
        fuchikoma.lock()
        time.sleep(1)
        fuchikoma.unlock()
        time.sleep(1)
        fuchikoma.shoot()
        time.sleep(1)
        fuchikoma.load_water()
        time.sleep(1)

    except KeyboardInterrupt:
        logger.info("Program interrupted by user.")
    except Exception as e:
        logger.error("An error occurred: %s", e)
    finally:
        logger.info("Exiting program.")

