import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

SERVO_PIN = 18
PWM_FREQUENCY = 50
DUTY_CYCLE_MIN = 2.5
DUTY_CYCLE_MAX = 12.5
PAUSE_SECONDS = 0.8
HEART_RATES = [62, 75, 88, 110, 95]

_running = True
_servo = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def calculate_angle(heart_rate):
    if heart_rate <= 0:
        return 0.0
    return (heart_rate / 150.0) * 180.0


def main():
    global _servo

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _servo = PWMOutputDevice(
            SERVO_PIN,
            frequency=PWM_FREQUENCY,
            initial_value=0.0,
        )
    except Exception as exc:
        print(f"Error: Failed to initialize PWM on GPIO{SERVO_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for heart_rate in HEART_RATES:
            if not _running:
                break

            angle = calculate_angle(heart_rate)
            duty = (angle / 180.0) * (DUTY_CYCLE_MAX - DUTY_CYCLE_MIN) + DUTY_CYCLE_MIN

            try:
                _servo.value = duty / 100.0
            except Exception as exc:
                print(f"Error: Failed to set servo PWM duty cycle: {exc}", file=sys.stderr)
                break

            print(f"Heart Rate: {heart_rate} bpm  |  Servo Angle: {angle:.1f} degrees")

            if _running and heart_rate < 100:
                time.sleep(PAUSE_SECONDS)

    except Exception as exc:
        print(f"Error: Unexpected runtime error: {exc}", file=sys.stderr)

    finally:
        if _servo is not None:
            try:
                _servo.value = 0.0
                _servo.close()
            except Exception:
                pass
        print("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

