import signal
import sys
import board
import busio
import adafruit_tcs34725

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_i2c():
    """Initializes the I2C bus on the Raspberry Pi."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to verify a device is present
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()
        if 0x54 in devices:
            return i2c
        else:
            print("Error: No TCS34725 sensor found at I2C address 0x54.")
            return None
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_color_sensor(i2c_bus):
    """Initializes the TCS34725 color sensor."""
    try:
        color_sensor = adafruit_tcs34725.TCS34725(i2c_bus)
        # Configure the sensor for 50 ms integration time and 4x gain
        color_sensor.integration_time = adafruit_tcs34725.INTEGRATIONTIME_50MS
        color_sensor.gain = adafruit_tcs34725.GAIN_4X
        return color_sensor
    except Exception as e:
        print(f"Error initializing color sensor: {e}")
        return None

def read_color_data(color_sensor):
    """Reads color data from the TCS34725 sensor."""
    try:
        red, green, blue, clear = color_sensor.color_rgb_bytes
        return red, green, blue, clear
    except Exception as e:
        print(f"Error reading color data: {e}")
        return 0, 0, 0, 0

def determine_dominant_color(image_file_name):
    """Determines the dominant color in an image using a color counting method."""
    try:
        from PIL import Image
        image = Image.open(image_file_name)
        image = image.resize((100, 100))
        pixels = image.load()
        color_counts = {}
        for x in range(image.width):
            for y in range(image.height):
                color = pixels[x, y]
                color_counts[color] = color_counts.get(color, 0) + 1
        dominant_color = max(color_counts, key=color_counts.get)
        return dominant_color
    except Exception as e:
        print(f"Error determining dominant color: {e}")
        return (0, 0, 0)

def main():
    """Main function to read color data and determine dominant color."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    color_sensor = initialize_color_sensor(i2c_bus)
    if color_sensor is None:
        i2c_bus.deinit()
        sys.exit(1)

    try:
        while running:
            red, green, blue, clear = read_color_data(color_sensor)
            print(f"Raw Color Data: Red={red}, Green={green}, Blue={blue}, Clear={clear}")

            image_file_name = "image.jpg"
            dominant_color = determine_dominant_color(image_file_name)
            print(f"Dominant Color: {dominant_color}")

            time.sleep(1)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        print("Cleaning up resources...")
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

