import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class ModbusRTU:
    """
    A class to encapsulate Modbus RTU communication with a servo motor controller.
    Provides methods for reading and writing holding registers over UART.
    """

    def __init__(self, port="/dev/serial0", baudrate=115200, timeout=1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self._running = True

    def _signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        self._running = False

    def _open_serial(self):
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logger.info(f"Serial port {self.port} opened successfully.")
        except serial.SerialException as e:
            logger.error(f"Error opening serial port {self.port}: {e}")
            self.ser = None

    def _close_serial(self):
        if self.ser and self.ser.is_open:
            try:
                self.ser.close()
                logger.info(f"Serial port {self.port} closed.")
            except serial.SerialException as e:
                logger.error(f"Error closing serial port {self.port}: {e}")
            finally:
                self.ser = None

    def _calculate_crc(self, data):
        crc = 0xFFFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x0001:
                    crc = ((crc >> 1) ^ 0xA001) & 0xFFFF
                else:
                    crc >>= 1
        return crc

    def _send_and_receive(self, address, functioncode, data):
        if not self.ser or not self.ser.is_open:
            logger.warning("Serial port not open. Cannot send data.")
            return None

        try:
            frame = bytes([address, functioncode]) + data + bytes([self._calculate_crc(frame + data) & 0xFF, (self._calculate_crc(frame + data) >> 8) & 0xFF])
            self.ser.reset_input_buffer()
            self.ser.write(frame)
            self.ser.flush()

            response = self.ser.read(256)
            if not response:
                logger.warning("No response received from device.")
                return None

            if len(response) < 2:
                logger.warning(f"Short response from device: {len(response)} bytes.")
                return None

            crc_received = (response[-2] << 8) | response[-1]
            crc_calculated = self._calculate_crc(response[:-2])
            if crc_received != crc_calculated:
                logger.warning(f"CRC mismatch: received 0x{crc_received:04X}, calculated 0x{crc_calculated:04X}")
                return None

            return response
        except serial.SerialException as e:
            logger.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error during communication: {e}")
            return None

    def _read_holding_registers(self, address, register, count):
        if count < 1 or count > 2047:
            logger.error(f"Invalid count: {count}. Must be between 1 and 2047.")
            return None

        data = bytes([(register >> 8) & 0xFF, register & 0xFF, count * 2])
        response = self._send_and_receive(address, 3, data)
        if response is None:
            return None

        if len(response) < 3:
            logger.warning(f"Short response from device: {len(response)} bytes.")
            return None

        if response[1] != 3:
            logger.warning(f"Function code mismatch: expected 3, got {response[1]}.")
            return None

        if response[2] != count * 2:
            logger.warning(f"Unexpected register count: expected {count * 2}, got {response[2]}.")
            return None

        if len(response) < 3 + count * 2:
            logger.warning(f"Short data length: expected {3 + count * 2}, got {len(response)}.")
            return None

        return list(response[3:])

    def _write_holding_register(self, address, register, value):
        data = bytes([(register >> 8) & 0xFF, register & 0xFF, (value >> 8) & 0xFF, value & 0xFF])
        response = self._send_and_receive(address, 6, data)
        if response is None:
            return False

        if len(response) < 3:
            logger.warning(f"Short response from device: {len(response)} bytes.")
            return False

        if response[1] != 6:
            logger.warning(f"Function code mismatch: expected 6, got {response[1]}.")
            return False

        return True

    def _read_holding_register(self, address, register):
        return self._read_holding_registers(address, register, 1)[0]

    def _write_holding_registers(self, address, register, values):
        if len(values) < 1 or len(values) > 2047:
            logger.error(f"Invalid number of values: {len(values)}. Must be between 1 and 2047.")
            return False

        data = bytes([(register >> 8) & 0xFF, register & 0xFF]) + bytes([(v >> 8) & 0xFF, v & 0xFF] for v in values)
        response = self._send_and_receive(address, 16, data)
        if response is None:
            return False

        if len(response) < 3:
            logger.warning(f"Short response from device: {len(response)} bytes.")
            return False

        if response[1] != 16:
            logger.warning(f"Function code mismatch: expected 16, got {response[1]}.")
            return False

        return True

    def read_holding_registers(self, address, register, count):
        if not self._running:
            logger.warning("Modbus communication stopped.")
            return None

        if self.ser is None or not self.ser.is_open:
            logger.warning("Serial port not open. Cannot read registers.")
            return None

        try:
            return self._read_holding_registers(address, register, count)
        except Exception as e:
            logger.error(f"Error reading holding registers: {e}")
            return None

    def read_holding_register(self, address, register):
        if not self._running:
            logger.warning("Modbus communication stopped.")
            return None

        if self.ser is None or not self.ser.is_open:
            logger.warning("Serial port not open. Cannot read register.")
            return None

        try:
            return self._read_holding_register(address, register)
        except Exception as e:
            logger.error(f"Error reading holding register: {e}")
            return None

    def write_holding_register(self, address, register, value):
        if not self._running:
            logger.warning("Modbus communication stopped.")
            return False

        if self.ser is None or not self.ser.is_open:
            logger.warning("Serial port not open. Cannot write register.")
            return False

        try:
            return self._write_holding_register(address, register, value)
        except Exception as e:
            logger.error(f"Error writing holding register: {e}")
            return False

    def write_holding_registers(self, address, register, values):
        if not self._running:
            logger.warning("Modbus communication stopped.")
            return False

        if self.ser is None or not self.ser.is_open:
            logger.warning("Serial port not open. Cannot write registers.")
            return False

        try:
            return self._write_holding_registers(address, register, values)
        except Exception as e:
            logger.error(f"Error writing holding registers: {e}")
            return False

    def close(self):
        self._running = False
        self._close_serial()


def main():
    signal.signal(signal.SIGINT, ModbusRTU._signal_handler)
    signal.signal(signal.SIGTERM, ModbusRTU._signal_handler)

    try:
        motor = ModbusRTU(port="/dev/serial0", baudrate=115200, timeout=1.0)
        motor._open_serial()

        if motor.ser is None or not motor.ser.is_open:
            logger.warning("Serial port not available. Skipping read/write tests.")
        else:
            logger.info("Reading holding register 0x0001...")
            value = motor.read_holding_register(0x01, 0x0001)
            if value is not None:
                logger.info(f"Register 0x0001 = 0x{value:04X}")
            else:
                logger.warning("Failed to read register 0x0001.")

            logger.info("Writing value 0x0002 to register 0x0001...")
            success = motor.write_holding_register(0x01, 0x0001, 0x0002)
            if success:
                logger.info("Write successful.")
            else:
                logger.warning("Write failed.")

    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        if 'motor' in locals():
            motor.close()


if __name__ == "__main__":
    main()

