import RPi.GPIO as GPIO
import time
import sys

# GPIO pin definitions (BCM numbering)
MOTOR_PWM_PIN = 17
MOTOR_DIRECTION_PIN = 22
PWM_FREQUENCY = 100  # Hz

# Global PWM object for cleanup
pwm_motor = None

def setup_gpio():
    """Initialize GPIO pins and PWM."""
    global pwm_motor
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(MOTOR_PWM_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_DIRECTION_PIN, GPIO.OUT)
        pwm_motor = GPIO.PWM(MOTOR_PWM_PIN, PWM_FREQUENCY)
        pwm_motor.start(0)  # Start with 0% duty cycle (motor off)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        cleanup_gpio()
        sys.exit(1)

def set_motor_speed(speed_percent):
    """Set motor speed as a percentage (0-100)."""
    if pwm_motor is None:
        print("PWM not initialized.", file=sys.stderr)
        return
    try:
        speed_percent = max(0, min(100, speed_percent))
        pwm_motor.ChangeDutyCycle(speed_percent)
    except Exception as e:
        print(f"Error setting motor speed: {e}", file=sys.stderr)

def set_motor_direction(forward):
    """Set motor direction: True = forward, False = backward."""
    if pwm_motor is None:
        print("PWM not initialized.", file=sys.stderr)
        return
    try:
        GPIO.output(MOTOR_DIRECTION_PIN, GPIO.HIGH if forward else GPIO.LOW)
    except Exception as e:
        print(f"Error setting motor direction: {e}", file=sys.stderr)

def stop_motor():
    """Stop the motor by setting PWM to 0% duty cycle."""
    if pwm_motor is not None:
        try:
            pwm_motor.ChangeDutyCycle(0)
        except Exception as e:
            print(f"Error stopping motor: {e}", file=sys.stderr)

def cleanup_gpio():
    """Stop motor and release GPIO resources."""
    stop_motor()
    if pwm_motor is not None:
        try:
            pwm_motor.stop()
        except Exception:
            pass
    GPIO.cleanup()

def main():
    """Main control loop."""
    setup_gpio()
    try:
        while True:
            # 100% speed forward
            set_motor_speed(100)
            set_motor_direction(True)
            time.sleep(1)

            # 50% speed forward
            set_motor_speed(50)
            set_motor_direction(True)
            time.sleep(1)

            # 0% speed forward
            set_motor_speed(0)
            set_motor_direction(True)
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

