        steps = abs(steps)
        direction = GPIO.LOW
    else:
        direction = GPIO.HIGH

    for _ in range(steps):
        for half_step in range(HALF_STEPS):
            for pin in STEPPER_PINS:
                GPIO.output(pin, (half_step >> (HALF_STEPS - 1 - pin)) & 1)
            time.sleep(STEP_DELAY)

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup failed: {e}", file=sys.stderr)

def main():
    """Main function to control the stepper motor."""
    setup_gpio()

    try:
        bearing = float(input("Enter the bearing (0-360): "))
        if not 0 <= bearing <= 360:
            print("Error: Bearing must be between 0 and 360 degrees.", file=sys.stderr)
            sys.exit(1)

        steps = int(round(bearing / 360.0 * HALF_STEPS))
        print(f"Rotating to bearing: {bearing:.2f} degrees, steps: {steps}")

        rotate_stepper(steps)
        time.sleep(HOLD_TIME)
        print("Rotation complete.")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except ValueError:
        print("Error: Invalid input. Please enter a numeric value.", file=sys.stderr)
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

