import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
SAMPLE_INTERVAL = 5
LOG_FILE = 'co2_readings_log.txt'

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_co2_level(serial_port):
    try:
        with serial.Serial(serial_port, BAUD_RATE, timeout=TIMEOUT) as ser:
            raw = ser.readline()
            if not raw:
                return None
            payload = raw.decode('ascii', errors='replace').strip()
            if not payload:
                return None
            return int(payload)
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except ValueError as e:
        print(f"Invalid data received (not numeric): {e}", file=sys.stderr)
        return None

def log_co2_reading(co2_level, log_file):
    timestamp = datetime.now().isoformat(timespec='seconds')
    try:
        with open(log_file, 'a') as f:
            f.write(f"{timestamp}, {co2_level}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    print("Starting CO2 monitoring...")
    while _running:
        co2_level = read_co2_level(SERIAL_PORT)
        if co2_level is not None:
            print(f"CO2 Level: {co2_level} ppm")
            log_co2_reading(co2_level, LOG_FILE)
        else:
            print("Failed to read CO2 level.")
        for _ in range(SAMPLE_INTERVAL):
            if not _running:
                break
            time.sleep(1)
    print("CO2 monitoring stopped.")

if __name__ == "__main__":
    main()

