import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
FLOW_THRESHOLD = 10.0
FLOW_PIN = 17

running = True

def signal_handler(sig, frame):
    global running
    running = False

def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FLOW_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=SERIAL_TIMEOUT)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue

                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                try:
                    flow = float(line)
                except ValueError:
                    print(f"Invalid data received (not a number): {line!r}", file=sys.stderr)
                    continue

                print(f"Flow Rate: {flow:.2f} L/min")

                if flow > FLOW_THRESHOLD:
                    GPIO.output(FLOW_PIN, GPIO.HIGH)
                else:
                    GPIO.output(FLOW_PIN, GPIO.LOW)

            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            except OSError as e:
                print(f"I/O error: {e}", file=sys.stderr)
                break

            time.sleep(1)

    finally:
        try:
            ser.close()
        except Exception:
            pass
        GPIO.cleanup()
        print("Resources cleaned up.")

if __name__ == "__main__":
    main()

