import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'
READ_INTERVAL = 1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_flow_rate(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Invalid data received (not a float): {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None

def log_flow_rate(flow_rate, log_file):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} - Flow Rate: {flow_rate:.2f} L/min\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file {log_file}: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_port = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        sys.exit(1)

    try:
        while _running:
            flow_rate = read_flow_rate(serial_port)
            if flow_rate is not None:
                print(f"Flow Rate: {flow_rate:.2f} L/min")
                log_flow_rate(flow_rate, LOG_FILE)
            time.sleep(READ_INTERVAL)
    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

