import signal
import sys
import time
from dataclasses import dataclass
from typing import Optional

import serial

# Constants for GPS module configuration
GPS_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1  # seconds


@dataclass
class GPS_readings:
    """Data class to store GPS readings."""
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    """
    A class to read and parse GPS data from a UART device.
    """

    def __init__(self, port: str = GPS_PORT, baudrate: int = BAUD_RATE, timeout: int = TIMEOUT):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection: Optional[serial.Serial] = None

    def connect(self) -> bool:
        """
        Establishes a connection to the GPS module.
        Returns True if successful, False otherwise.
        """
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            if not self.serial_connection.is_open:
                raise serial.SerialException(f"Failed to open {self.port}")
            print(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            print(f"Error connecting to GPS: {e}", file=sys.stderr)
            self.serial_connection = None
            return False

    def disconnect(self) -> None:
        """
        Disconnects from the GPS module if connected.
        Idempotent: no-op if already closed.
        """
        if self.serial_connection is not None and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                print("Disconnected from GPS.")
            except serial.SerialException as e:
                print(f"Error disconnecting from GPS: {e}", file=sys.stderr)
            finally:
                self.serial_connection = None

    def read_gps_data(self) -> Optional[GPS_readings]:
        """
        Reads a line from the GPS module and parses it into a GPS_readings object.
        Returns None if no data is available or parsing fails.
        """
        if self.serial_connection is None or not self.serial_connection.is_open:
            print("Serial connection is not established.", file=sys.stderr)
            return None

        try:
            raw_line = self.serial_connection.readline()
            if not raw_line:
                # Timeout occurred with no data
                return None

            line = raw_line.decode("ascii", errors="replace").strip()

            if not line.startswith("$GPGGA"):
                return None

            # Parse GPGGA sentence
            parts = line.split(",")
            if len(parts) < 15:
                print(f"Incomplete GPGGA sentence (expected 15 fields, got {len(parts)}): {line}", file=sys.stderr)
                return None

            # Validate talker ID
            talker_id = parts[0][0:6]
            if talker_id != "GPGGA":
                print(f"Invalid talker ID: {talker_id}. Expected 'GPGGA'.", file=sys.stderr)
                return None

            # Extract latitude and longitude
            latitude_raw = parts[2]
            longitude_raw = parts[4]

            # Validate latitude and longitude
            if not latitude_raw or not longitude_raw:
                print("Invalid latitude or longitude data.", file=sys.stderr)
                return None

            latitude_direction = parts[3]
            longitude_direction = parts[5]

            latitude = self._convert_to_decimal(latitude_raw, latitude_direction)
            longitude = self._convert_to_decimal(longitude_raw, longitude_direction)

            # Extract altitude
            altitude = self._convert_to_float(parts[9])

            # Extract satellite count
            satellite_count = self._convert_to_int(parts[7])

            return GPS_readings(latitude, longitude, altitude, satellite_count)

        except ValueError as e:
            print(f"Error converting data to numeric format: {e}", file=sys.stderr)
            return None
        except IndexError as e:
            print(f"Error parsing GPGGA sentence: missing field at index {e}", file=sys.stderr)
            return None
        except serial.SerialException as e:
            print(f"Serial communication error: {e}", file=sys.stderr)
            return None

    @staticmethod
    def _convert_to_decimal(raw_value: str, direction: str) -> Optional[float]:
        """Converts a raw latitude or longitude value to decimal degrees."""
        if not raw_value or not direction:
            return None

        try:
            degrees = float(raw_value[:2])
            minutes = float(raw_value[2:])
            decimal_degrees = degrees + (minutes / 60.0)

            if direction in ("S", "W"):
                decimal_degrees = -decimal_degrees

            return decimal_degrees

        except ValueError:
            return None

    @staticmethod
    def _convert_to_float(value: str) -> Optional[float]:
        """Converts a raw altitude value to a float."""
        if not value:
            return None

        try:
            return float(value)
        except ValueError:
            return None

    @staticmethod
    def _convert_to_int(value: str) -> Optional[int]:
        """Converts a raw satellite count value to an integer."""
        if not value:
            return None

        try:
            return int(value)
        except ValueError:
            return None


def main() -> None:
    """Main function to initialize and run the GPS data acquisition."""
    gps_reader = GPSReader()

    def signal_handler(signum, frame):
        print(f"\nSignal {signum} received. Shutting down...")
        gps_reader.disconnect()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps_reader.connect():
        print("Failed to connect to GPS. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            gps_data = gps_reader.read_gps_data()
            if gps_data:
                print(f"GPS Data: Latitude={gps_data.latitude}, Longitude={gps_data.longitude}, "
                      f"Altitude={gps_data.altitude}, Satellites={gps_data.satellite_count}")
            else:
                print("No GPS data received.")
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        gps_reader.disconnect()


if __name__ == "__main__":
    main()

