import serial
import time
import signal
import sys

class GPS:
    """
    A class to control a GPS module over the UART on a Raspberry Pi.
    """

    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        """
        Initializes the GPS object.

        Args:
            port (str): The serial port device path.
            baud (int): The baud rate for communication.

        Raises:
            serial.SerialException: If the serial port cannot be opened.
        """
        self.port = port
        self.baud = baud
        self.serial_connection = None
        self._closed = False

        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baud,
                timeout=1
            )
        except serial.SerialException as e:
            raise serial.SerialException(f"Failed to open serial port {self.port}: {e}") from e

    def attach(self):
        """
        Powers on the GPS module.

        Returns:
            bool: True if the power on command was sent successfully, False otherwise.
        """
        if self._closed:
            return False

        try:
            self.serial_connection.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            return True
        except serial.SerialException as e:
            print(f"Error powering on GPS: {e}", file=sys.stderr)
            return False

    def detach(self):
        """
        Powers off the GPS module.

        Returns:
            bool: True if the power off command was sent successfully, False otherwise.
        """
        if self._closed:
            return False

        try:
            self.serial_connection.write(b'AT+CGNSPWR=0\r\n')
            return True
        except serial.SerialException as e:
            print(f"Error powering off GPS: {e}", file=sys.stderr)
            return False

    def get_data(self):
        """
        Reads data from the GPS module.

        Returns:
            str: The parsed data, or None if no valid data is available.
        """
        if self._closed:
            return None

        try:
            if self.serial_connection.in_waiting > 0:
                data = self.serial_connection.readline().decode('utf-8', errors='ignore').strip()
                if data.startswith('$GPRMC'):
                    return data
                return None
            return None
        except serial.SerialException as e:
            print(f"Error reading from GPS: {e}", file=sys.stderr)
            return None

    def close(self):
        """
        Closes the serial port connection.
        """
        if self._closed:
            return

        self._closed = True
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
            except serial.SerialException as e:
                print(f"Error closing serial port: {e}", file=sys.stderr)

