import serial
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.uart = None
        self._running = True

    def connect(self):
        try:
            self.uart = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except OSError as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            self.uart = None
            return False

    def read_data(self):
        if self.uart is None or not self.uart.is_open:
            logging.error("UART connection is not open.")
            return None
        try:
            raw = self.uart.readline()
            if not raw:
                return None
            return raw.decode('utf-8', errors='ignore').strip()
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            self.close()
            return None
        except UnicodeDecodeError as e:
            logging.error(f"Unicode decode error: {e}")
            return None

    def parse_gga(self, line):
        if not line.startswith('$GPGGA') and not line.startswith('$GNGGA'):
            return None
        try:
            fields = line.split(',')
            if len(fields) < 15:
                logging.warning(f"Incomplete GGA sentence: {line!r}")
                return None
            utc_time = fields[1]
            latitude = self._parse_coordinate(fields[2], fields[3])
            longitude = self._parse_coordinate(fields[4], fields[5])
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA sentence: {e}")
            return None

    def _parse_coordinate(self, raw_value, direction):
        if not raw_value:
            return None
        try:
            degrees = float(raw_value[:2])
            minutes = float(raw_value[2:])
            decimal = degrees + minutes / 60.0
            if direction in ('S', 'W'):
                decimal = -decimal
            return decimal
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing coordinate: {e}")
            return None

    def close(self):
        if self.uart is not None:
            try:
                if self.uart.is_open:
                    self.uart.close()
                    logging.info("UART connection closed.")
            except serial.SerialException as e:
                logging.error(f"Error closing UART: {e}")
            finally:
                self.uart = None

    def stop(self):
        self._running = False

def main():
    gps = SimpleGPS()
    def signal_handler(sig, frame):
        logging.info("Shutdown signal received.")
        gps.stop()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not gps.connect():
        sys.exit(1)
    try:
        while gps._running:
            data = gps.read_data()
            if data:
                gga = gps.parse_gga(data)
                if gga:
                    logging.info(f"GPS Data: {gga}")
            else:
                logging.debug("No GPS data received.")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        gps.close()

if __name__ == '__main__':
    main()

