import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_access(tag_id):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a') as log_file:
            log_file.write(log_entry)
    except IOError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)
    print(f'Access granted for RFID Tag: {tag_id}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Failed to open serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                raw_data = serial_connection.readline()
                if not raw_data:
                    continue
                tag_id = raw_data.decode('ascii', errors='replace').strip()
                if tag_id:
                    log_access(tag_id)
            except serial.SerialException as e:
                print(f'Serial communication error: {e}', file=sys.stderr)
                break
            except Exception as e:
                print(f'Unexpected error reading from serial port: {e}', file=sys.stderr)
                break
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

