import serial
import time
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_pulse_oximeter_data(serial_port):
    """Reads data from the pulse oximeter and returns it as a string."""
    try:
        data = serial_port.readline()
        if not data:
            return None
        return data.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading from serial port: {e}", file=sys.stderr)
        return None

def process_pulse_oximeter_data(data):
    """Processes the received data and returns a tuple of heart rate and SpO2."""
    if not data:
        return None, None

    try:
        parts = data.split(',')
        if len(parts) != 2:
            print(f"Warning: Expected 2 comma-separated fields, got {len(parts)}: {data!r}", file=sys.stderr)
            return None, None

        heart_rate = int(parts[0])
        spo2 = int(parts[1])
        return heart_rate, spo2

    except ValueError as e:
        print(f"Warning: Invalid data format: {data!r}: {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected error processing data: {e}", file=sys.stderr)
        return None, None

def display_pulse_oximeter_data(heart_rate, spo2):
    """Displays the heart rate and SpO2 data."""
    if heart_rate is not None and spo2 is not None:
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

def main():
    """Main function to read and display pulse oximeter data."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            pulse_oximeter_data = read_pulse_oximeter_data(serial_connection)
            if pulse_oximeter_data:
                heart_rate, spo2 = process_pulse_oximeter_data(pulse_oximeter_data)
                display_pulse_oximeter_data(heart_rate, spo2)

            # Sleep in small increments to allow prompt signal handling
            slept = 0
            while _running and slept < READ_INTERVAL:
                time.sleep(0.1)
                slept += 0.1

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

