import sys
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("web_service")

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1.0
PAUSE_BEFORE_READ = 0.1

_running = True


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _idn_query(ser):
    """Send *IDN? and return the stripped response as text/html."""
    try:
        ser.reset_input_buffer()
        ser.write(b"*IDN?\n")
        ser.flush()
        time.sleep(PAUSE_BEFORE_READ)
        raw = ser.read(ser.in_waiting or 1024)
        if not raw:
            return ""
        return raw.decode("ascii", errors="replace").strip()
    except serial.SerialException as exc:
        log.error("Serial read error: %s", exc)
        return ""
    except OSError as exc:
        log.error("OS error during serial read: %s", exc)
        return ""


def _get_data(ser):
    """Return the current list as JSON."""
    return json.dumps(list(data))


def _get_item(ser, item_id):
    """Return the item with the given ID, or None if not found."""
    for item in data:
        if item["id"] == item_id:
            return json.dumps(item)
    return None


def _post_item(ser, item_id, name, done):
    """Append a new item with the given ID, defaults done=False."""
    if item_id is None or not isinstance(item_id, int) or item_id < 0:
        return None
    if name is None:
        name = ""
    if done is None:
        done = False
    item = {"id": item_id, "name": name, "done": bool(done)}
    data.append(item)
    return json.dumps(data)


def _post_json(ser, data):
    """Parse JSON from the request body and return the updated list."""
    try:
        body = data.get("data", "")
        if not isinstance(body, (list, dict)):
            return None
        items = []
        for item in body:
            if not isinstance(item, dict):
                return None
            item_id = item.get("id")
            if item_id is None or not isinstance(item_id, int) or item_id < 0:
                return None
            name = item.get("name", "")
            if not isinstance(name, str):
                return None
            done = item.get("done", False)
            if not isinstance(done, bool):
                return None
            items.append({"id": item_id, "name": name, "done": bool(done)})
        return json.dumps(items)
    except (json.JSONDecodeError, TypeError) as exc:
        log.error("JSON decode error: %s", exc)
        return None


class WebServiceHandler(BaseHTTPRequestHandler):
    """HTTP request handler for the web service."""

    def do_GET(self):
        if self.path == "/version":
            self.send_response(200)
            self.send_header("Content-Type", "text/html")
            self.end_headers()
            self.wfile.write(_idn_query(ser).encode("utf-8"))
        elif self.path == "/getdata":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(_get_data(ser).encode("utf-8"))
        elif self.path.startswith("/getset/"):
            try:
